quests[57582] = { id = 57582, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Executor of N'Zoth" }
quests[57583] = { id = 57583, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Through the Veil", description = "I like you, youngling. You put in the work while the others sit in their fancy court, leaving old Marasmius to keep the fae rings thriving.\n\nHere, take one of my spores back with you to the Heart of the Forest. Find somewhere nice and cozy for me to rest, will you?\n\nCome back and visit me whenever you like. Cort and I can keep an eye on things for now, but there will always be plenty for you to do here. Might even be something special in it for you.", completion = "Ahh, it's nice to stretch out again. I've missed this place, you know.\n\n<Marasmius pauses for a moment.>\n\nDon't tell anyone here I said that, all right?", objectives = "Find somewhere to plant Marasmius in the Heart of the Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57584] = { id = 57584, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Fate Most Noble", description = "Welcome, Worthy One!\n\nI am Greeter Mnemis. It is my duty and pleasure to assist you on this, your first day among the kyrian.\n\nAllow me to congratulate you. Your fate is reserved for the most noble of souls. Only those who lived a life of service may call Bastion home.\n\nI am certain you have many questions- all new aspirants do! Please allow me the honor of introducing you to the next chapter of your existence.\n\nWe will begin when you are ready.", progress = "Please alert me to your needs and concerns, Worthy One.", completion = "I hope that was informative and relaxing.", objectives = "Learn more about the kyrian.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57585] = { id = 57585, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of the Void" }
