quests[57621] = { id = 57621, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Summoning Ritual" }
quests[57634] = { id = 57634, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bring Your Own", description = "Scunner, a roiling mass of flesh and slime, has crawled out of the ruins of the House of Plagues. \n\nHe emits a toxic vapor that impairs the functions of those who attempt to fight him. You can try it, Maw Walker, but it's doubtful you could hurt him on your own.\n\nConstructs are built to fight creatures like Scunner. So gather a force of them and eliminate the threat.", completion = "Very fine work, Maw Walker.", objectives = "Defeat Scunner.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57636] = { id = 57636, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pride of Place", description = "The Mantle of the Primus. It belongs on his statue.\n\nYou were the one to recover it, so you will have the honor of returning it to its proper place.", progress = "Each answer leads to another question. Each enemy defeated reveals another secret.", completion = "We must find the source of Gharmal's stockpiled anima. But for now, let us enjoy our victory.", objectives = "Place the Mantle of the Primus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57637] = { id = 57637, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disturbance Detected: Firelands", description = "You're early {name}, I hadn't even sent for you yet.\n\nAnother temporal disturbance has flared up, this time in the Firelands. If Ragnaros hadn't been dealt with when he was, well, you've already seen one way the end time could turn out.\n\nSome intricate time weaving is required to be sure you catch Ragnaros early, but still after whatever is causing the disturbance. Whoever is doing this isn't messing around any more.", progress = "Bring me the temporal anomaly as soon as you can, so we can get back to yesterday's problems tomorrow.", completion = "Oh no, time-locking?! Who knows how long this had been there before we were able to detect it! This is far worse than I had imagined...", objectives = "Relive the siege of the Firelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57638] = { id = 57638, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Korrak the Bloodrager", description = "The indigenous Winterax trolls of the region are ruthless savages that would love nothing more than to have our bones added to their foul stew.\n\nWe must show them our might!\n\nWe have recovered tomes from their caves that detail their leadership hierarchy. The artifacts indicate that their leader, Korrak the Bloodrager, tends to remain hidden until given a reason to make his presence known.\n\nDeath to Korrak would mean death to Winterax Clan! Slay him and return.", progress = "Be warned, soldier: The Frostwolf also hunt for Korrak.", completion = "Well done. With Korrak dead, our full attention can be focused upon purging the Frostwolf filth from the region.", objectives = "According to legend, the leader of the mighty Winterax trolls appears at will to wreak havoc on the denizens of Alterac Valley.\n\nShould Korrak make himself known, destroy him and return to Lieutenant Haggerdin in the Dun Baldar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57639] = { id = 57639, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Legend of Korrak", description = "The invading Stormpike are not the only threat in the region, soldier. The war in the Valley is waged on two fronts. The cannibal Winterax trolls also vie for power.\n\nThey are lead by Korrak the Bloodrager - a cruel and cunning beast.\n\nA strike against Korrak could prove to be a crushing blow to the Winterax clan. Slay the beast and be rewarded!", progress = "Be warned, soldier, the Stormpike also hunt for Korrak.", completion = "Only the invading Stormpike armies remain, soldier. Well done!", objectives = "According to legend, the leader of the mighty Winterax trolls appears at will to wreak havoc on the denizens of Alterac Valley.\n\nShould Korrak make himself known, destroy him and return to Warmaster Laggrond.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57640] = { id = 57640, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Master Ryson's All Seeing Eye", description = "Your war in the heart of Alterac means nothing to the Syndicate, {class}. We will do as we have always done: Wait until a clear victor rises from the ashes and rubble of this madness and then strike.\n\nThat, however, is not why we are here now. The All Seeing Eye has been lost - taken by the Winterax trolls of the region.\n\nRecover the Eye and our services shall be yours - for whatever time remains for your side.\n\nReturn to me once you acquire the eye so that I may examine you.\n\n<Master Ryson grins.>", completion = "<Master Ryson examines the Eye.>\n\nNow you shall be witness to the awesome power of the All Seeing Eye!", objectives = "Recover Master Ryson's All Seeing Eye from the Winterax caves and return it to Master Ryson.\n\nBe warned, it is said that Master Ryson's All Seeing Eye carries with it a terrible curse!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57641] = { id = 57641, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Master Ryson's All Seeing Eye", description = "Your war in the heart of Alterac means nothing to the Syndicate, {class}. We will do as we have always done: Wait until a clear victor rises from the ashes and rubble of this madness and then strike.\n\nThat, however, is not why we are here now. The All Seeing Eye has been lost - taken by the Winterax trolls of the region.\n\nRecover the Eye and our services shall be yours - for whatever time remains for your side.\n\nReturn to me once you acquire the eye so that I may examine you.\n\n<Master Ryson grins.>", completion = "<Master Ryson examines the Eye.>\n\nNow you shall be witness to the awesome power of the All Seeing Eye!", objectives = "Recover Master Ryson's All Seeing Eye from the Winterax caves and return it to Master Ryson.\n\nBe warned, it is said that Master Ryson's All Seeing Eye carries with it a terrible curse!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57642] = { id = 57642, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Winter Veil Gift", objectives = "A small tag on this present reads:\n\nHappy holidays, {name}!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57643] = { id = 57643, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gently Shaken Gift", objectives = "This present looks like it has been shaken a few times. The tag on it reads:\n\nTo a very special {race} {class}.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57644] = { id = 57644, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Friend Left Behind", description = "I would care for nothing more than to serve as navigator again, but my dearest friend suffers. I cannot stand to abandon him.\n\nI can feel Twigin now. He struggles against the binding web of the spiders who once served us. More victims of this senseless conflict...\n\nThough it pains me to say it, you must slay our spiders and gather their caustic venom. You can then use it to free Twigin.\n\nIf not out of empathy, rescue him for the sake of your plans. My skills will be useless without his direction.", progress = "Please spare him this pain.", completion = "Thank you for returning me to my sister.", objectives = "Rescue Twigin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57646] = { id = 57646, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Tithelord", description = "With his army defeated, the Tithelord is vulnerable. Now, he has but a small contingent to protect him. Let us strike him down decisively. \n\nHe draws power from these anima wells, keeping it all for himself. If you can hold his attention, I can not only empower you to defeat him but also disable the wells.\n\nSpeak to me when you are ready to begin. When the time is right, the baroness will lead our new recruits into battle.", progress = "An Archlich? This complicates things.", completion = "A Maldraxxus archlich manipulating our Harvesters... This cannot go unanswered.\n\nI am pleased that Baroness Draka is equally eager to strike at Kel'Thuzad directly.\n\nGeneral Draven will ready our armies while Laurent repairs the mirror. Be ready and take these as we prepare. We will ensure vengeance is met alongside our new allies.", objectives = "Slay The Tithelord and collect the Medallion of Envy.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57648] = { id = 57648, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Impossible Plan", description = "Everything is in place for us to seize a necropolis. I will coordinate our efforts and meet you at the Seat of the Primus. \n\nDraka will undoubtedly commend you on your success. I, however, will do so once our mission is complete.", completion = "You've done well, Maw Walker.", objectives = "Report back to Draka at the Seat of the Primus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57649] = { id = 57649, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Whisper of Hope", description = "Akarek's demise has cast a dark shadow upon our house... but it is in the shadows where we thrive.\n\nI know that not all the Eyes have perished. They could lie in wait, hidden for eternity, if such was demanded of them.\n\nBut it is time to reclaim our destiny. Take my sigil through the wreckage and awaken any Eyes who remain.\n\nWe will seize our victory.", completion = "The baroness inspires great dedication. I trust in her plans.", objectives = "Use Vashj's Sigil to rally survivors of the House of Eyes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57650] = { id = 57650, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Better Off Dead", description = "Our defense is tenuous at best, but the enemy is still hesitant to attack.\n\nAs long as they fear us, they won't be probing our defenses. \n\nYou must keep the pressure on the enemy.  Attack their positions all along our line.", objectives = "Eliminate Enemy forces and positions.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57651] = { id = 57651, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trouble in the Banks", description = "Ah, be welcome in my glade, Maw Walker. You are safe here.\n\nWhile it is regrettable that Sorcha must wait for her weapons, it is of paramount importance that I keep my charges safe. I will do anything to prevent them from suffering as the rest of Ardenweald.\n\nPerhaps I could ask a small favor of you. I have not heard from the gatherers at the Banks of Life in some time. Would you mind checking on them to make sure they are well? I would go myself, but I must deal with Sorcha. Seek out Foreman Thorodir.", completion = "Ah, the Lady sent you? Well, I have some bad news.", objectives = "Find Foreman Thorodir near the Banks of Life.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57652] = { id = 57652, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Supplies Needed: Amber Grease", description = "Foreman,\n\nOur supply of gris is running low. You know as well as I do that there is no end to Glitterfall Basin's need of it.\n\nI've overheard from some of the other workers that you have a bit of a gorm problem. But the bigger the gorm, the bigger the gris, right?\n\nIf you happen to harvest some more, we can certainly put it to good use.\n\n<The work order is signed: \"Cavina.\">", progress = "Do you have something for me?", completion = "It really is a remarkable substance. We use it in practically everything! Construction, mending, crafts, and it can even be added to rations.", objectives = "Collect 6 Giant Gorm Gris.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57653] = { id = 57653, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unsafe Workplace", description = "You've returned just in time! Fae are in danger!\n\nIt seems our actions have enraged the gorm. They are even more aggressive than they were before!\n\nWhile some fae were able to evacuate, there are still many who are trapped down there.\n\nTake this jar and slather anyone you find with a generous helping. That should heal their wounds and give them a chance to escape.", completion = "Thank you for rescuing them.", objectives = "Heal 10 wounded sylvar in the Banks of Life.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57655] = { id = 57655, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Supplies Needed: More Husks!", description = "I need more husks, Thorodir! The Lady herself wants to make sure we are outfitted with the finest armor.\n\nThey've been soaking in the waters long enough to be workable. Find some time to retrieve them before our hunters find themselves without adequate protection.\n\n<The work order is signed: \"Cavina.\">", progress = "What's that you have there?", completion = "I'm glad you found my note. Husks such as these need to soak in running water for several days before they can be shaped without breaking.\n\nAt least you were able to salvage something.", objectives = "Collect 6 Treated Gorm Husks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57656] = { id = 57656, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gifts of the Forest", description = "These gorm have gone out of control! We need to stop them.\n\nI have a plan, but I cannot do it on my own. We lure the gormlings to the Banks of Life by using special totems that are drained of their anima. If you can retrieve the wood required for the totem, I can prepare the ritual.\n\nTake these pipes. Find the Culex trees growing on the banks and play a song for them. You will recognize them by their pale green leaves. The wood must be given freely for the ritual to work.", progress = "We need that lure for my clever plan. It's very clever, you're going to love it.", completion = "Good. This should do it!", objectives = "Collect 3 Culexwood Branches.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57657] = { id = 57657, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tied Totem Toter", description = "Hope you've caught your breath.\n\nThe totem is now a big, tasty beacon to all the nearby gorm. They're going to want to eat it and you're going to be carrying it!\n\nWe need to rehome the smaller ones. If they stay here they're just going to get big and angry again. If you can drop off a few groups of them outside the Banks of Life we can make sure they find their way to more balanced feeding grounds.\n\nLet Thorodir know when you're done. I will let him know the plan.", completion = "Fluttercatch always was a clever one. Well done.", objectives = "Lure 30 gormlings to the wrangler in the Banks of Life.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57658] = { id = 57658, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Final Leg", description = "Please, I must get to Glitterfall Basin.\n\nI thought I was being careful. I did not realize I was being hunted until it was too late. Such is the nature of the forest.\n\nI am too close to fall here. The Lady herself invited me to come join her. She said I would be safe.\n\nCan you take me to her?", objectives = "Deliver Windchaser to Glitterfall Basin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57660] = { id = 57660, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Grove of Creation", description = "I probably would have been digested if not for you. And while that sounds like a fascinating phenomenon, I am glad I did not experience it... firsthand.\n\nYou have a knack for solving problems and you're not afraid to get your hands dirty with our tools. Might I suggest paying a visit to Glitterfall Basin, to the west? It is home to our finest minds and workshops, and I am sure they could use your help in this drought.\n\nThe Lady of the Falls is droman there. She will know where you can best help!", completion = "Master Sha'lor sent you? Such a darling.\n\nNext time you see him you can tell him that it's perfectly safe here.", objectives = "Speak with the Lady of the Falls in Glitterfall Basin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57661] = { id = 57661, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Silk Shortage", description = "We are running short on silk! We use it for so many things, like instruments, weapons, and tools. But our supply has dried up!\n\nWe are in desperate need for fresh silk.\n\nOur main hub of silk production is in the Gossamer Cliffs. If you could, seek out Caretaker Lillythistle, and see what the holdup is!", completion = "Of course silk shipments have stopped!\n\nThe entire glade has been attacked by changelings and spriggans! Our poor silkstriders are so stressed out, we can't get any silk from them!\n\nCan you help us?", objectives = "Find Lillythistle in the Gossamer Cliffs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57670] = { id = 57670, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unbeelievable Quality", description = "<Now that your harvester has matured, the Honeyback hive is creating additional honey.\n\nSomeone in Brennadam could certainly find a use for this honey.>", completion = "I don't believe it! Honey from bees instead of those... blobs... at the meadery?\n\nI'll make sure this gets to Raimond.", objectives = "Take the Collected Tidebloom Honey to \"Nasty\" Buck in Brennadam.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57671] = { id = 57671, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meeting Blightcaller", description = "There's no time to rest, {name}.\n\nOur troops are returning from our latest skirmish against the Alliance. Many are dead or severely injured. \n\nOur warchief, the Dark Lady Sylvanas Windrunner, has requested aid in this war against the Alliance.\n\nI recommended you for an operation that is planned. Nathanos Blightcaller is waiting to speak with you.\n\nBefore you go, I'll catch you up on what has happened.", completion = "Hmph, so you're the recruit that saved Breka's son from an island? I thought you'd be taller.\n\nThe Dark Lady has need of capable soldiers. Breka recommended you for this task.\n\n<Nathanos sneers>\n\nWe'll see how long you last.", objectives = "Speak with Warleader Breka, then meet Nathanos Blightcaller.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57676] = { id = 57676, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Things That Haunt Us", description = "As you will soon learn, a ritual cleansing can be a... painful process.\n\nIn most cases, the upwelling of emotion is harmless. It can even generate anima under the right circumstances.\n\nHowever... sometimes the result is far less pleasant. Negative memories can take a form of their own and manifest in a violent fashion.\n\nI fear Pelagos' attempt at cleansing has brought forth such monsters. You must destroy them, and quickly.", progress = "Is it done?", completion = "The things that bind us can be violent. The insight we gain is no reason to let them run rampant.", objectives = "Slay 12 memories.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57677] = { id = 57677, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Soulbind In Need", description = "Pelagos is my Soulbind. He is my brother, my closest friend, my mentor, and my student. He knows me completely, and I him. It is a bond stronger than any other.\n\nThat he now struggles is a torment to me, but I am forbidden from intervening. An aspirant must succeed or fail on their own merits, or the trial is forfeit.\n\nI am bound by this law... but you are not.\n\nPlease bring Pelagos back to me. This will not be his last trial. Not when he may finally have a chance.", completion = "I owe you a great debt, {name}.", objectives = "Rescue Pelagos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57686] = { id = 57686, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Eternal Traveler", description = "Hail, mortal.\n\nFor untold ages, my kind has traversed the myriad realms of reality. We have beheld phenomena that you cannot begin to comprehend. But there is much you must learn of what awaits you on the horizon.\n\nThe power of Death is on the rise. The veil weakens between your world and the Shadowlands.\n\nWhen a mortal life expires, an echo of it remains behind. The most powerful mortals leave the most resonant echoes.\n\nBring these to me, that I might study them... to both our benefits.", progress = "One can glean so much knowledge from the mortal realm.", completion = "Mortal lives are so fragile... and yet, any one of them can alter the fabric of reality.", objectives = "Gather Echoes of Mortality from living creatures.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57689] = { id = 57689, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prince Renathal", description = "You! They say you are a Maw Walker. Well, time to put that to the test.\n\nMy master, Prince Renathal, was the one who started the rebellion. He knew Denathrius was working towards something truly nefarious, and attempted to stop him.\n\nThe rebellion failed, and Renathal was flung into the Maw.\n\nI propose you and I venture into the Maw. There is an old device here that only you will be able to use. Together, we can recover my Prince. You need him, if you are to have any hope of success.", progress = "Your fighting style lacks... finesse.", completion = "So this is the Maw. I can feel it leeching my essence. Be on your guard.", objectives = "Enter the Maw to find Prince Renathal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57690] = { id = 57690, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cages For All Occasions", description = "Okay, do not lose focus. I can feel Renathal's presence. It is faint but I can sense he is outside of the tower, at least.\n\nCome, let's find him and get out of here.", completion = "I recognize you. Azeroth has been very busy lately, and her champions have been very much at the forefront of events. We must talk as soon as time allows.", objectives = "Find Prince Renathal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57691] = { id = 57691, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Royal Key", description = "I am not about to question whatever twist of fate led you to me. Your timing could not be better.\n\nThis cage was custom built to contain me. There is one key, and of course it is on the armor of that large brute over there.\n\nVanquish him and take the key. Be swift, the Jailer's eyes are always on this area.", progress = "There was an age when I knew how to pick a lock even this elaborate. Sadly that was so long ago I seem to have fallen out of practice.", completion = "Well, you are quite resourceful. Give me twenty five of your kind and some proper gear and we could defeat the Master.", objectives = "Recover Renathal's Cage Key.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57693] = { id = 57693, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Torghast, Tower of the Damned", description = "My allies were taken into the Tower of the Damned, and so we must follow.\n\nI do not think we must venture deep into those halls, which is good as I do not believe either of us is in shape for a fight like that.\n\nCome, let us find our way to one of the most dangerous towers in all of existence.", completion = "It is only a matter of time before the Master detects my presence. We must be swift and violent of action if we are to stop Sire Denathrius.", objectives = "Recover Renathal's Allies from Torghast, Tower of the Damned.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57694] = { id = 57694, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Refuge of Revendreth", description = "Sinfall is more than a ruin. It was once a place of dark magic and experimentation.\n\nWhen the Light retaliated and scorched the Ember Ward, the walls of this place stood. It is fortified, supplied, and filled with secrets. A perfect staging ground for our upcoming conflict.\n\nBut first, take me to meet these allies who led you to Vorpalia. We must take stock of what resources we have to work with.", completion = "So few left, but we will make do.", objectives = "Gather your allies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57700] = { id = 57700, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest", sourceObjective = "Acquire 1 Rich Jelly and return it to the Hivemother.", sourceObjectiveStatus = "unverified-source-field" }
quests[57701] = { id = 57701, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[57702] = { id = 57702, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[57703] = { id = 57703, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[57709] = { id = 57709, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Aspirant's Crucible", description = "I have given Kalisthene's words some thought.\n\nIf you are to learn our ways, we should proceed as if you were an aspirant yourself. The next step is to journey through the Aspirant's Crucible.\n\nIt is a place of reflection, training, and cleansing. For an aspirant, it is where they prepare for the long journey ahead. For you... I hope you will learn how you might help us in this time of crisis.\n\nWord of your arrival has likely spread. We will not keep them waiting.\n\nTake my steed, and go in service.", completion = "<The Forgelite studies you for a moment, then nods.>\n\nWelcome. You are not what we expected, but we are glad to have you nonetheless.", objectives = "Ride Theonara to Aspirant's Crucible.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57710] = { id = 57710, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Life of Service", description = "Curious. You are unlike any aspirant that has come before, that much is certain.\n\nYou will notice that we have an audience. It has been a long time indeed since we welcomed another to the path. We are all eager to see what deeds brought you to us.\n\nSimply approach the dais before you and gaze into the flame. The Watcher will pull forth your memories of those you served in life, and you will be transported back to those moments to aid them once more.", progress = "Such a display is certain to raise our spirits.", completion = "I confess... I was hoping for a small spectacle to lift the spirits of the aspirants in my care.\n\nI was not expecting to have my own lifted, as well. Thank you for that.", objectives = "Witness memories of your past life.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57711] = { id = 57711, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Forge Gone Cold", description = "I have seen firsthand that you are a most capable soul.\n\nKleia has told me of your purpose here. She has spoken of the hopes she places in you. I am not yet certain if I am ready to do the same.\n\nThere is one small task that I would set before you, however. My forge has grown cold without anima to keep it burning bright. I long to practice my craft again.\n\nMy helper, whom you have met before, can elaborate on our needs.\n\nYou will find Sika near the forge. I will follow shortly.", completion = "Hello again! This one is glad to see you!", objectives = "Speak to Sika.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57712] = { id = 57712, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suggested Reading", description = "Greetings. You must be the new aspirant everyone is talking about.\n\nI thought you might like to learn more about us. There are three tomes that would serve you well as a starting point, but they are not currently in the library.\n\nAspirant Leda was the last to hold \"Worlds Beyond Counting.\" Aspirant Ikaran has yet to return \"The Infinite Treatises.\"\n\nIt seems \"Bear Witness: The Watcher's Code\" went missing some time ago. I would search the village.\n\nOnce returned, you can read them at your leisure.", progress = "Did you find the scrolls I suggested?", completion = "I will see that they are returned to their proper places for everyone to enjoy.\n\nI appreciate your help in retrieving them, and I hope they were informative.", objectives = "Retrieve \"The Infinite Treatises\", \"Worlds Beyond Counting\", and \"Bear Witness: The Watcher's Code.\"", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57713] = { id = 57713, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Work of One's Hands", description = "Too long have my hands been idle!\n\n<Forgelite Sophone smiles warmly at you.>\n\nYou cannot know what this means to me, but I might be able to show you. For your aid in restoring my forge, please allow me to craft you a piece of armor.\n\nIt will not be an extravagant affair, but through good works we grow to know ourselves better.\n\nI will need your aid once more. Sika and I will guide you on the specifics. All you need to do is listen and do as instructed.\n\nWhat do you say?", progress = "There is no greater pleasure than creating something from nothing.", completion = "I hope you like it. It is far from my finest work, but it will serve you well while you are here.", objectives = "Assist Forgelite Sophone in crafting a piece of armor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57714] = { id = 57714, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assessing Your Spirit", description = "It is clear to all that you are indeed a skilled combatant.\n\nThere is one challenge here that continues to test even the strongest among us. I would have you attempt to best a well-known centurion, beloved by all aspirants. It is called Athanos.\n\nConsider this a test of your spirit.\n\nIf you can withstand this trial, then I will deem you ready for what lies ahead.", progress = "<Kleia watches you impassively.>", completion = "This is always a painful lesson. We do not think less of you for it.", objectives = "Challenge Athanos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57715] = { id = 57715, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Archon's Answer", description = "Your cleansing is complete, and you are whole.\n\nOur plan was a success. Undergoing such a rite, so soon after your arrival, has attracted Kalisthene's attention once more. \n\nNow is our opportunity to request an audience with the Archon.\n\nStand before her and be proud of what you have accomplished. No matter what happens now, you have done all that any aspirant could hope to.", completion = "You are worthy of Bastion's grace, {name}. May it serve you well.", objectives = "Speak to Kalisthene.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57716] = { id = 57716, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Wayward Disciple?", description = "While you are here and as yet unaffected by this--rash of doubt, we shall call it--there is one other errand I would ask of you.\n\nI sent one of the disciples to investigate reports of the fallen fleeing our temple. For their own safety, they must be taken to the Temple of Loyalty.\n\nDisciple Nikolon has yet to return. If he is to be found nearby, it will be near the border of our temple to the north.\n\nPlease, seek him out and ensure that he is not injured or in peril.", progress = "Have you located Disciple Nikolon?", completion = "Thank you for bringing him to me, {name}. He is in a worse state than any of us might have guessed.", objectives = "Locate Disciple Nikolon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57717] = { id = 57717, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Step Back From That Ledge, My Friend", description = "This disciple... such emotion...\n\n<Eridia stares at Nikolon for a long moment.>\n\nRarely do ascended require such rigorous cleansing, but I cannot deny what is readily apparent. This disciple will fall if I do not intervene.\n\nThere is no time to lose. Come. I will instruct you.\n\n... I only hope we are not too late.", completion = "<Eridia grips her hammer with pale knuckles.>\n\nHow... how are they so numerous?", objectives = "Assist Eridia in cleansing Disciple Nikolon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57718] = { id = 57718, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bound in Stone", description = "Some of our warriors were camped in the small settlement near Guo-Lai when the Baruk invaded the area. Some managed to escape, but they returned with tales of their brothers and sisters in arms being petrified by the mogu stoneshapers into living statues!\n\nWe can't leave our warriors behind! \n\nThe stoneshapers must carry some means to reverse the spell and free them from their stone prisons. Bring our soldiers back!", completion = "Your deeds honor us, {name}. \n\nI can't imagine what fate would've befallen our warriors if left to the Baruk.", objectives = "Collect Stoneshaper Rods from Baruk Stoneshapers and use them to free 5 Petrified Warriors in the Ruins of Guo-Lai.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57719] = { id = 57719, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dangerous Discourse", description = "<The scroll's runes shift and change as you attempt to read it. At first glance, it appears illegible.\n\nSimilar scrolls have appeared all over the Temple of Purity.\n\nEridia will be interested in these.>", progress = "We must defend the temple, {name}.", completion = "These words... this voice...\n\nHow do I know this voice?", objectives = "Collect 6 Dark Sermons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57720] = { id = 57720, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champions of the Mogu", description = "These lesser clans warring with each other in the Vale need to be taught their place.\n\nSeek out their champions and eliminate them. Show them that only the Rajani have rightful claim here!", completion = "The wayward clans should learn that such fate awaits all that would oppose the Rajani.\n\nTake your reward, outsider. We are done here.", objectives = "Defeat 3 rare enemies while the Mogu are invading the Vale of Eternal Blossoms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57721] = { id = 57721, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spoils of War", description = "The warring clans are relentless and our warriors are going through armor faster than I can keep it repaired.\n\nIf you find yourself in battle with the other clans, see if you can salvage any undamaged armor pieces from their soldiers. We should not let good resources go to waste.", progress = "What have you managed to salvage, outsider?", completion = "The wayward clans should learn that such fate awaits all that would oppose the Rajani.\n\nTake your reward, outsider. We are done here.", objectives = "Collect 12 pieces of Salvaged Mogu Armor from mogu enemies in the Vale of Eternal Blossoms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57722] = { id = 57722, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Empty Stables", description = "Just look at the stables, {name}! Empty! The Stormpike Brigade has no rams to ride - the cavalry is defunct.\n\nYou must help us, soldier. Take this training collar and enter the wilds of this valley. Locate the Alterac rams that roam throughout the area and use the collar to snare one. When you have captured a ram, return it to me and I shall place it in our stable.\n\nWhen we have enough rams, the ram rider commander will be notified. With your help, the cavalry will be reborn!", progress = "Without your help, the Stormpike Ram Riders would not have mounts to ride into battle. You do us a great service!", completion = "The stables will be full in no time at all. Keep up the good work!", objectives = "Locate an Alterac Ram in Alterac Valley. Use the Stormpike Training Collar when you are near the Alterac Ram to 'tame' the beast. Once tamed, the Alterac Ram will follow you back to the Stable Master. Speak with the Stable Master to earn credit for the capture.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57723] = { id = 57723, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Empty Stables", description = "The war in the valley has taken its toll on our soldiers. We must revitalize our forces!\n\nIf we can fill up the stables, the Wolf Riders will once more be able to ride out into the field of battle.\n\nTake this muzzle and track down the frostwolves that inhabit the nearby forest. Once you find a wolf, use the muzzle to tame the beast. Bring the tamed beast back to me so that I may place it in the stable.\n\nWhen we have enough wolves stabled, the Wolf Riders will rejoin their patrol on our front lines.", progress = "Without your help, the Frostwolf Wolf Riders would not have mounts to ride into battle. You do us a great service!", completion = "I can only hope that those charged with collecting ram hides are as determined as you, {name}.\n\nAt this rate, we will have the stables full in a matter of hours!", objectives = "Locate a Frostwolf in Alterac Valley. Use the Frostwolf Muzzle when you are near the Frostwolf to 'tame' the beast. Once tamed, the Frostwolf will follow you back to the Frostwolf Stable Master. Speak with the Frostwolf Stable Master to earn credit for the capture.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57724] = { id = 57724, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Securing Sinfall", description = "They're all still active...\n\nThe stoneborn, the gargon, the stone fiends... All of 'em!\n\nDon't got much time. They're always watching.\n\n<Breakfist points up.>\n\nVulca told me to follow that big beam of Light in the sky.\n\nGoes to a tower guarded by a big old brute, though. Couldn't get in.", completion = "Now that we have cleared out the Master's forces, let us continue the search for Prince Renathal!", objectives = "Clear out Sinfall and make it safe for Theotar and the other venthyr.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57727] = { id = 57727, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stonevigil Unrest", description = "Greetings, {name}. I'm sure you've met my associate, Baroness Draka.\n\nI have recruited her to help us with the growing threat of the Tithelord.  His involvement with the Maldraxxi renegades is troubling.\n\nOne conspiracy begets another. So I recruited Draka to help us end it.\n\nWe must not treat this situation lightly. We first need to put an end to his oppression of Stonevigil Overlook. That way we can we win over the hearts and minds of his subjects.", completion = "Thank you for your quick arrival, {name}.", objectives = "Meet Prince Renathal and Baroness Draka at Stonevigil Overlook.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57728] = { id = 57728, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault: The Endless Swarm", description = "The mantid swarm is surging! There's no way the Golden Lotus will be able to handle this many of them.\n\nWe must do something to drive them back!", progress = "Are you with me?", completion = "It looks like they're retreating. That was a close one. \n\nThe Vale should be safe, for now.", objectives = "Drive back the Mantid Assault in the Vale of Eternal Blossoms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57729] = { id = 57729, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Estate", description = "A window of opportunity has presented itself to us, {name}.\n\nWith his supply line cut off, Vartox dead, and people turned against him, the Tithelord should be no match for us. However, I must admit I do fear what tools he may have acquired from his Maldraxxi cohorts.\n\nHis base of operations is just down the road: the Caretaker's Manor, named for the Harvester whom he replaced.\n\nWe will meet you there.", completion = "Let us finish what we started.", objectives = "Meet Prince Renathal at The Caretaker's Manor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57730] = { id = 57730, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zinfizzlex's Portable Shredder Unit", description = "I'm as anxious as you are to try out my portable shredder unit, {race}, but before I can make the kit, I'm going to need materials - lots of materials!\n\nTo be exact, I'm going to need a mountain of thorium, mithril, and iron. I will also need one steamsaw per unit. You'll have to get those at the lumber mill.\n\nWhen I was nosing around in here (before my capture) I noticed a pile of steamsaws at the Frostwolf lumber camp.", progress = "Mountain is a technical term. It's a goblin engineer thing...", completion = "Here you go, {name}. Due to the, um, unstable nature of the jiggamadoos and sprockolozings of the unit, I can only guarantee that it will work for three days. After that...", objectives = "Master Engineer Zinfizzlex wants you to bring him the following:\n\n*30 Thorium Bars.\n\n*50 Mithril Bars.\n\n*75 Iron bars.\n\n*1 Steamsaw.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57731] = { id = 57731, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zinfizzlex's Portable Shredder Unit", description = "I'm as anxious as you are to try out my portable shredder unit, {race}, but before I can make the kit, I'm going to need materials - lots of materials!\n\nTo be exact, I'm going to need a mountain of thorium, mithril, and iron. I will also need one steamsaw per unit. You'll have to get those at the lumber mill.\n\nWhen I was nosing around in here (before my capture) I noticed a pile of steamsaws at the Stormpike lumber camp.", progress = "Mountain is a technical term. It's a goblin engineer thing...", completion = "Here you go, {name}. Due to the, um, unstable nature of the jiggamadoos and sprockolozings of the unit, I can only guarantee that it will work for three days. After that...", objectives = "Master Engineer Zinfizzlex wants you to bring him the following:\n\n*30 Thorium Bars.\n\n*50 Mithril Bars.\n\n*75 Iron bars.\n\n*1 Steamsaw.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57737] = { id = 57737, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ramkahen Rescue", description = "Mar'at was overrun by those foul K'thir before we could safely evacuate our citizens. \n\nI fear the worst has happened to them.\n\nPlease, if anyone is left alive within the city, tell them to come to Ramkahen.", completion = "I appreciate your effort in rescuing our people, {name}.", objectives = "Rescue 6 Mar'at Villagers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57743] = { id = 57743, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Conquest's Reward", objectives = "Your prowess on the field of battle is without peer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
