quests[57765] = { id = 57765, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Conquest's Reward", objectives = "Your prowess on the field of battle is without peer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57766] = { id = 57766, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "War with the Horde", description = "Good to see you've received proper training as a {class}.\n\nWe'll need it for what's next. The Alliance's war with the Horde has reached a fevered pitch... and we've lost a lot of good soldiers.\n\nKing Anduin is looking for aid in an operation to bolster our forces. I told him you'd be a good fit for the job.\n\nBefore you meet him, let me get get you caught up on what has been happening so far.", objectives = "Speak with Captain Garrick to find out what is happening between the Horde and Alliance.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57768] = { id = 57768, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Conquest's Reward", objectives = "Your prowess on the field of battle is without peer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57769] = { id = 57769, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Conquest's Reward", objectives = "Your prowess on the field of battle is without peer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57771] = { id = 57771, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Unwelcome Incursion", description = "The Tithelord sent his stoneborn to further reap the anima from these citizens. How long has this been going on? These acts reek of unfathomable greed.\n\nThere is but one answer to this dilemma: to send a message. Crush these oppressors. Drain their anima and return it to Stonevigil's anima well.\n\nThe incursion will be dealt with and the downtrodden's spirits lifted. Two birds, one stone.\n\n<Draka hands you an anima container.>\n\nTake this. I stole it from one of the guards earlier.", completion = "Stone to rubble. \n\nGreat work.", objectives = "Drain anima from 12 Stonevigil stoneborn. Then, refuel the anima well in the town center.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57772] = { id = 57772, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fangs and Minds", description = "The denizens of Stonevigil have been wrung dry by the Tithelord's greed. \n\nWhile some have taken up arms against these injustices, most are too downtrodden to act. We need them on our side to take him down.\n\n<Prince Renathal hands you a heavy scroll dripping with anima.>\n\nGo, show them the hypocrisy of their oppressor! Send them to me with the promise of sanctuary.", completion = "More hands for the rebellion. They can taste the truth.", objectives = "Use Renathal's Decree to inspire 8 Stonevigil Citizens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57773] = { id = 57773, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Close to Tears", description = "Our warriors have observed foul manifestations coming forth from numerous void tears within the surrounding jungle. \n\nThey have been but mere weaklings, clearly intended to test our defenses before the real forces arrive.\n\nIf we do not deal with this threat now, however, it will only be a matter of time until we are overrun by their fodder.\n\nFind a way to close those portals!", progress = "Have you had any luck with the portals yet?", completion = "That should help to hold back the tide... for now.", objectives = "Find and close 3 Void Tears in Uldum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57774] = { id = 57774, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nine Lives", description = "Scouts have returned recently, nearly on the verge of death, with reports that I find... disconcerting.\n\nNeferset have been spotted wandering the streets of their city to the south.\n\nThis would normally be no cause for alarm, except the Neferset were completely wiped out.\n\nI must ask you to investigate further... and if by some foul magic these reports turn out to be true, you must do whatever you can to contain this threat!", progress = "Have you news of Neferset City?", completion = "I cannot believe what I am hearing... \n\nThis is truly much worse than I feared.", objectives = "Destroy 8 Neferset Denizens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57778] = { id = 57778, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Maldraxxian Job", description = "We cannot hope to hold the Seat without a necropolis. Khaliiq reports that Vashj is ready to set her plan in motion.\n\nMeet with her and the other Eyes at Nurakkir. Do what must be done.", completion = "We are pleased to see your return.", objectives = "Meet with Whisperer Vyn at Nurakkir.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57787] = { id = 57787, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keep to the Path", description = "That's everything on the list for this part of the forest. Lady Moonberry said to meet her in Tirna Vaal. It's just down the road; I'm going to fly ahead so everyone knows to expect you.\n\nJust stay on the path and you won't be eaten. Probably. See you soon!", progress = "Hey! You survived!", completion = "Featherlight says you've kept up your end of our deal. That's great to hear!\n\nI have some news to share about getting you an audience with the Queen.", objectives = "Continue down the road toward Tirna Vaal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57816] = { id = 57816, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dreamweaver", description = "Troubled winds sweep across Tirna Vaal. The boughs tremble in concern over the Queen's arrival. All must be as it should be.\n\nDreamweaver's wings droop with the weight of worry. Chaos swirls around the wildseeds under his care.\n\nCalm the churning waters of the grove. Bring harmony to discord and let Dreamweaver flutter once more.", completion = "You're new, aren't you? Not a fae, not a soul, nor are you bound for a wildseed.\n\nAnd the droman sent you here to help me? Well, this just got very interesting.", objectives = "Speak with Dreamweaver in the Tranquil Pools.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57818] = { id = 57818, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nothing Goes to Waste", description = "The gormlings are industrious creatures. Naturally, they are our source of gorm gris.\n\nGormlings are cute, small, and hungry, like Gloober here! Except he is not hungry right now, because I just fed him. Look at that little belly...\n\n<Ahem>. I digress.\n\nGormlings will be drawn to consume anything that is not brimming with anima. They find it simply delicious. \n\nTake that wildseed there, and bring it into their pen. Then, see if you can get the gormlings to feast upon it!", progress = "Have you fed the gormlings?", completion = "Well done!\n\nThe gormlings may be easily distracted, sometimes, but they are such helpful little creatures.\n\nThat is, when they are small.\n\nThe big ones are a different matter. But don't worry about those! I'm sure we won't have to deal with them.", objectives = "Collect the Depleted Wildseed, place it in the gormling pen, and coax gormlings to eat it.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57824] = { id = 57824, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Collection Day", description = "Now, we can collect the gorm gris for Guardian Kota!\n\nOnce the gormlings have eaten something, we can 'encourage' them to give it back up. What they produce, we call gorm gris!\n\nMy Gormherd Branch should encourage them to do this safely. \n\nGo on, give it a try on good ol' Gloober first.\n\nWhat has me worried is how the other gormlings might behave. They have been acting so strangely lately!", progress = "I wonder what would happen if I overcharged the Gormherd Branch... would that be more efficient? Or would it make things explode?\n\n... probably explode.", completion = "Oh, this isn't right at all! The gormlings are supposed to return to their normal, adorable little selves.\n\nWhat in the Queen's name is happening to them?\n\nAnd there's no more gorm gris to give to Kota! This won't do at all.", objectives = "Use the Gormherd Branch on Gloober, then collect gorm gris from the Gorged Gormlings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57825] = { id = 57825, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Delivery for Guardian Kota", description = "This is most disturbing, indeed. The gorm are just too... wild, now!\n\nI wonder if the drought is making everything delicious to them, and that is why.\n\nThis isn't enough gorm gris, either. And I do not want to disappoint Kota..\n\nBut, I also don't want to put you through more trouble collecting it. I will go myself into the burrows nearby, to see if I can find any more for her.\n\nWould you take this gorm gris to her for me, please?", completion = "Master Sha'lor has gone to the burrows himself, to try and find more gorm gris?\n\n... for me?\n\nThat reckless, thick-horned sylvar! He will get himself killed!", objectives = "Deliver the gorm gris to Guardian Kota in Tirna Vaal.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57850] = { id = 57850, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Storied Partnerships" }
quests[57852] = { id = 57852, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dungeon Adventure" }
quests[57853] = { id = 57853, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battleforged Team" }
quests[57860] = { id = 57860, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "How to Become Forsworn", description = "The Forsworn have taken control of Kalliope's Rest and are looting its antiquities. They must be looking for the Spear of Kalliope, a relic of great power.\n\nTheir numbers are far too great and we are no match. Perhaps there is another way? \n\nA small group of aspirants is removing artifacts from the shrine. If you gather uniform pieces and an insignia from them, we can get you inside the shrine unnoticed.", progress = "Do you have everything we need to make a disguise?", completion = "What did you do to this armor? You are a savage, yet effective, fighter it seems.", objectives = "Collect 3 Forsworn Uniform Pieces and a Quartermaster's Insignia from within Kalliope's Rest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57861] = { id = 57861, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Just Act Natural", description = "With this disguise you will blend right in. I... know a Forsworn artificer on the inside who should prove useful. You need to remain convincing, however.\n\nThe most important thing is to get to Kalliope's spear before the Forsworn manage to do so. The shrine has many defenses, but it's only a matter of time before they find it.\n\nI am somewhat ashamed. Many of the aspirants here used to be friends. So much has been lost.", completion = "What is it? Don't just mill about.\n\nOh, it's you...", objectives = "Find Artificer Ligiea farther into Kalliope's Rest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57865] = { id = 57865, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ages-Echoing Wisdom", description = "Hmph. Even if I wanted to give her weapons, I cannot. My glade is under attack!\n\nMost of my people were driven out during the attack on the growthworks but a few of the elders stayed behind. Whether to delay the enemy or see the friends to safety, they are not here where it is safe.\n\nEach elder can perform extraordinary works and could make the weapons in no time at all. Rescue the elders and then we'll talk about using their talents for the good of Ardenweald.", completion = "Good! I am glad you found them alive. Of course, we will be unable to put them to work until the threat is dealt with and they are able to continue their crafts in peace. I'm sure Sorcha will understand.", objectives = "Locate Elder Gwenna, Elder Finnan, and Groonoomcrooek.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57866] = { id = 57866, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Idle Hands", description = "If you want my help then you are going to need to help me first.\n\nThere is a group of spriggans that have assaulted the growthworks to the northeast. They are causing all manner of havoc and I simply will not abide this trespass into my lands.\n\nGo there and teach them a lesson. If they will not flee, then slay them on the spot!", completion = "Good. It is the way of nature for the stronger to prevail.", objectives = "Slay 12 Brittlebark invaders in the Growthworks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57867] = { id = 57867, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sweat of Our Brow", description = "Ah, an outsider! You are perfect for this task.\n\nThe spriggans are known for their mischief. They have been cursing our tools and supplies and trapping unsuspecting workers!\n\nLike our curses, they must obey the rules. You'll need shimmerdust for baskets, thread made of gossamer for harps, and minty fresh breath for the soulwebs. How odd.\n\nGood luck and let the Lady of the Falls know when you're done. She'll be delighted to hear it!", completion = "Cursed tools? And you brought them back? Un-cursed!? I must say, I was not entirely expecting you to be quite so successful.", objectives = "Disarm 6 trapped tools.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57868] = { id = 57868, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Craftsman Needs No Tools", description = "Oh, I am quite all right! There's just one little thing....\n\nOne of these fiends made off with my lucky mallet! I simply cannot leave my mallet behind. I do not even use it much any more, but it is quite lucky and I always keep it with me.\n\nPlease, I cannot even think about building anything without it. Do keep an eye out for it, will you?", progress = "It is small, and quite lucky. I am sure you will know it when you see it.", completion = "Oh, you found it! How lucky, do you see?", objectives = "Find Finnan's Lucky Mallet.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57869] = { id = 57869, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spirit-Gathering Labor", description = "You are not like the others.\n\nThe waters here carry deep power. Power most have forgotten. But the tirnenn forget very little.\n\nPower flows through the earth just as water flows with power. Flows can be trapped for a time, dripping. Drop by drop they drip into vessels.\n\nSearch for the vessels beneath the falls. Collect the power.", progress = "Drip, drip, go the falls. Drop, drop, goes the power. Power of the earth.", completion = "Much power courses through. We need only the smallest dustings. Your labors please me.", objectives = "Collect 6 River Sediment.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57870] = { id = 57870, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Games We Play", description = "Do not worry about me. We have a bigger problem.\n\nI heard their leader around here somewhere during the attack. I have been keeping watch from here but I have not been able to see them. They must be using some sort of glamour to hide themselves.\n\nI have yet to meet a spriggan who can resist a game. If you find one eager to play and can win, then perhaps you can learn something about their leader.", completion = "Very interesting. This will be quite useful.", objectives = "Win the game of wits by using emotes to correctly answer the Playful Trickster's riddles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57871] = { id = 57871, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Outplayed", description = "Now we can strike down their leader, friend.\n\nIt just so happens that I have a large pouch of puffpetal powder right here. Why don't you take it and toss a few handfuls around the workshop floor at the top of the falls? If they are still there, I imagine they will have an... unfortunate reaction.\n\nWhile you do that I will gather the other elders and make our way to Glitterfall Basin. Speak with the Lady when your task is done.", completion = "Ah, the hero of the hour returns! Thank you for liberating my supplies. Our grove desperately needs them in these trying times.", objectives = "Defeat Wicked Wort.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57872] = { id = 57872, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bring More Friends!", description = "This is only the beginning, friend.\n\nI must thank you again for rescuing me. Now that we have found a safe route, I am but the first of many. Druids from all around Ardenweald have heard of the safety of this glade, and I wish to bring them all here.\n\nI have known Roriel for most of my time in this place. She is a capable healer, despite her appearance. She would be a fine addition to this place.\n\nShe was last seen near Tirna Fein to the west. Please let her know the way is clear.", sourceObjective = "Locate Roriel.", sourceObjectiveStatus = "unverified-source-field" }
quests[57873] = { id = 57873, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Word from Orsis", description = "As you can see, {name}, we have our hands full here dealing with these disgusting bugs.\n\nOur caravans from the south have stopped arriving and we have received disturbing news from the few who've made it back recently.\n\nI've sent a patrol toward Orsis to investigate; they are past due for a report back.\n\nCan I ask you to check in on them for me?", completion = "If the sun didn't take me, the bugs surely would have. Thank you {name}.", objectives = "Investigate the situation in Orsis.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57875] = { id = 57875, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mark of Humility", description = "Quartermaster, you've arrived.\n\nThose fools over there still haven't gotten past the first barrier. We need to get into that cave to have any chance at recovering the Spear of Kalliope.\n\nOur research discovered the phrase, \"Only the humble find their way. Even heroes kneel before virtue.\" But those fools have been working on that clue for ages.\n\nGo figure out the problem and get inside that cave. We need its mark to open the final vault.", progress = "Have you acquired the mark?", completion = "Well done, quartermaster. Well done. The Spear of Kalliope is almost within my grasp!", objectives = "Obtain the Mark of Humility from within the First Chamber of Kalliope.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57876] = { id = 57876, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The End of the Beginning", description = "<Renathal struggles to speak, his wounds evident.>\n\nI knew Denathrius had hoarded anima, but this... this is beyond imagining.\n\nThe Jailer will surely use this power to shatter his bonds. Should he break free of the Maw, all the realms of Death will fall.\n\nWe must continue to press the fight against Denathrius. Alas, we cannot hope to succeed alone.\n \nReturn to Oribos with Draven and speak to the Honored Voice, Tal-Inara. Tell her what you have seen this day and implore her to action.", completion = "We have sensed something horrific has happened. Quickly, tell me everything.", objectives = "Speak with the Voice of the Arbiter, Tal-Inara, in Oribos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57877] = { id = 57877, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Looming Dark", description = "It is good you have returned safely from Revendreth, {name}. We sensed a betrayal that has shifted the infinite threads of fate.\n\nThe Maw surges with power. We must know the cause.", progress = "As the bearer of this news, you must bear this burden as well.", completion = "You have done well. See that you continue to do so.", objectives = "Reveal the Jailer's plan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57878] = { id = 57878, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Choosing Your Purpose", description = "Each covenant is vital to the Shadowlands. Though they often seem at odds with one another, this too is part of the Purpose.\n\nAll the covenants need to grow strong to face the threat of the Jailer. But your efforts cannot be divided. They must be focused upon a single path. Other mortals may make a different choice.\n\nThe time has come for you to take a side. \n\nSpeak to your allies. Then make your choice at the map of the Shadowlands before me.", progress = "Have you made your decision yet?", completion = "All is as expected. Trust always in the Arbiter's plan.", objectives = "Speak to the Covenants. Decide how your path is entwined with the Purpose.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57880] = { id = 57880, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Estate Within the Old Gate", description = "I believe I know how we can obtain the Countess's medallion and avoid making any new enemies.\n\nBefore being cast out into the Light, I held a prominent position within the Countess's court. She bestowed upon me an estate with direct access to her private chambers. \n\nIf the estate still stands, you can use it to sneak into the Countess's manor and steal the medallion without ever drawing your weapon. \n\nTake this note to my trusted butler, Bogdan. He will provide whatever assistance you need.", progress = "What is this? A note from the Duke?", completion = "<Bogdan reads the words quickly, his eyes welling with tears as a smile spreads across his face.>\n\nThe Duke lives? What splendid news!", objectives = "Deliver Theotar's Note to Bogdan within the Old Gate.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57881] = { id = 57881, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Key to Rebuilding", description = "If we plan to revive the estate, we'll first need the keys!\n\nWhen Theotar was exiled to the Ember Ward, he lost all titles and property, meaning that the estate fell into the hands of another aristocrat. \n\nThe new owner is a mystery to me, but household staff almost always carry keys on them as they do their business within the Old Gate. \n\nRecover the key and we'll be on our way to rebuilding the manor.", progress = "Have you recovered the key?", completion = "Ah, this is it! We should have no trouble accessing the manor now.", objectives = "Recover an Ornate Key from Redelav house staff within the Old Gate.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57882] = { id = 57882, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reestablishing the Household", description = "Unfortunately, when ownership of the estate changed hands, the staff were all displaced and forced to find new work. Some of us found suitable roles within favorable households. After all, everyone needs a sommelier! \n\nOthers were not so lucky. They're still here in the Old Gate, taking odd jobs to survive. I'm sure they'll be eager to work for the Duke again once they learn we're reestablishing the household.\n\nSeek them out and present this offer of employment.", completion = "Don't worry about Florin. He'll come around.", objectives = "Deliver offers of employment to Dumitra, Elena, and Florin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57884] = { id = 57884, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reclaiming Thornhill Manor", description = "I've done some digging and discovered that Viscount Nicolae is the new inhabitant of Thornhill Manor. \n\nA vile thing, he is. It'll take us weeks to rid the estate of his stench!\n\nHopefully, you can rid us of him in a much timelier fashion. \n\nI'll gather the rest of the staff and together we can reclaim Thornhill Manor.", progress = "I cannot stand the thought of someone else occupying Thornhill Manor.", completion = "Why would our lady choose such a lout as her paramour? Regardless, Thornhill Manor is ours once again.", objectives = "Kill Viscount Nicolae and reclaim Thornhill Manor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57885] = { id = 57885, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Discreet Entrance", description = "I can assure you--this is not how we left the place. Never would we ever let the manor fall into such a state. \n\nAt least the mirror is still intact, that's what's important. You can use it to enter the Countess's private chambers discreetly and recover the medallion. \n\nGo, quickly, before word spreads of what we've done. We'll do our best to restore the manor while you're gone.", completion = "How nice it is to finally come face to face with the revered Maw Walker.", objectives = "Enter the Countess's chambers by using the ornate mirror.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57886] = { id = 57886, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Meal and A Deal", description = "Even though you arrived here uninvited, you weren't unexpected. I know all that goes on within my district. \n\nAs such, let us share a meal and speak of the matters at hand.\n\nI believe there's a way in which we can both get what we want.", progress = "Please, enjoy my hospitality.", completion = "So, we have a deal then?", objectives = "Enjoy The Countess's hospitality while listening to her proposal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57887] = { id = 57887, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Killing the Messenger", description = "I make it my business to know what is going on within my district. \n\nTraditionally we use stone fiends to relay messages, but my informants have alerted me to some suspicious communications going on within the Old Gate. \n\nA venthyr has been hired to run missives between two undisclosed parties. When someone puts that much effort into concealing their identity, it can never be good.\n\nFind this courier and recover whatever missives they might be carrying.", progress = "Has it been done?", completion = "<The Countess maintains a stoic expression as she carefully scans the missive, her grip tightening the longer she reads.>\n\nThis letter was penned by Andrei of House Iremoore. I'd know that scrawl anywhere. And it would appear he's plotting to overthrow me.", objectives = "Recover a Treasonous Missive from a Redelav Courier.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57888] = { id = 57888, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Invitation to Treachery", description = "While the missive made it clear that Andrei is displeased with my position, nothing in the letter identifies his co-conspirator. \n\nAll we really know is that they are trying to gain access to my soiree this evening so they can carry out their plans. Let's make it easy for them, shall we? \n\nHead into the Redelav District and deliver an invite to the prominent houses. This way, we'll be sure the traitors show up.", completion = "No one will be able to turn down an invite to one of my infamous soirees.", objectives = "Deliver invitations to each of the noble houses within the Redelav District.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57889] = { id = 57889, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "\"Accidental\" Arson", description = "It's no use trying to get Andrei to tell us who he's working with. He won't talk, and we can't risk alerting his accomplice. \n\nWe need to get rid of him, and it needs to look like an accident. \n\nOnce Andrei's been dealt with, set fire to his rug and let the whole estate burn down.  \n\nAndrei isn't someone you want coming into power. He's as ruthless as he is cruel.", completion = "You're quite thorough, aren't you? I can see the flames from here. While you were out I took the liberty of having some proper leg wear altered to fit you. I am sure I have you sized up properly.", objectives = "Kill Lord Andrei and set fire to his estate.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57890] = { id = 57890, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beautiful, But Deadly", description = "The Redelav District is home to the most affluent venthyr in all of Revendreth. Its denizens spare no expense on the upkeep of their extravagant gardens.\n\nWell worth the effort, I must say. For the Redelav District is the only place where Duskmire mushrooms can grow. They are as beautiful as they are deadly.\n\nWould you mind collecting a few? Their uses are varied, and it's always a good idea to have some on hand.", progress = "Do you have the mushrooms?", completion = "<The Countess inspects the mushrooms with a wry smile.>\n\nA rich color means the spores will be potent.", objectives = "Collect 50 Duskmire Mushrooms from gardens within the Redelav District.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57891] = { id = 57891, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mix, Mingle, and Meddle", description = "Once the party begins, I will be occupied with a plethora of nobles that wish to cling to my side. \n\nThis is why I need you to mingle. Speak with the attendees and see if you can determine which house is conspiring against me. \n\nBe warned, invited guest or not, these aristocrats can smell an outsider. You won't receive a warm welcome from everyone.", progress = "One among my guests is the traitor. I need you to find out who.", completion = "Have you identified the traitorous house?", objectives = "Attend the Countess's soiree and speak with guests to uncover the traitorous house.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57892] = { id = 57892, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enacting Immediate Justice", description = "There are likely many in attendance who wish me harm. \n\nI trust you have done your job in determining which house has been working with Andrei?\n\nOnce they are named, I trust you will enact immediate justice.", progress = "The traitorous house will be uncovered and swiftly dealt with.", completion = "Justice has been served, and an uprising quelled.", objectives = "Name the traitorous house and enact justice.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57893] = { id = 57893, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neither Enemy nor Ally", description = "I hope you now see the importance of the role I play. \n\nMy parties serve a greater purpose. Keeping the influential and elite entertained helps quell uprisings. If their minds are consumed by trivial things, they don't have time to plot or plan. \n\nSometimes, battles are best fought before they begin. Giving you my medallion is an example of that. \n\nWe may not be allies, but we are not enemies, either.", progress = "Have you secured the medallion?", completion = "The Countess gave it up without a fight? We might have an ally in her yet...", objectives = "Deliver the medallion to Prince Renathal in Sinfall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57895] = { id = 57895, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elysian Hold", description = "One more step yet remains before your initiation is complete.\n\nYou must now enter Elysian Hold, entryway to the rest of the Spires of Ascension and the vantage point from which the ascended safeguard Bastion and our aspirants in training.\n\nOnce there, we shall ensure you are fully acquainted with the hold's offerings. Since you lack wings, I shall escort you there.", completion = "Welcome home, {name}.", objectives = "Travel with Polemarch Adrestes to Elysian Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57897] = { id = 57897, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dangerous to Go Alone", description = "There is one last thing you must do before we can act to clean up Denathrius's chaos.\n\nYou must have a soulbind.\n\nAll kyrian undergo this sacred ritual--albeit typically many aeons before they stand before the Archon herself.\n\nSoulguide Daelia will guide you in this process. Seek her out in the chamber below.", completion = "I see even now that your soul burns brighter than most.", objectives = "Speak with Soulguide Daelia in the Sanctum of Binding.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57898] = { id = 57898, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Soul Meets Body", description = "To soulbind with another is not an irrevocable bond. However, it is not to be entered into lightly.\n\nYou will experience one another's pasts. Your hopes, fears, dreams, your very memories--if any still linger. You will become kindred spirits in the truest sense.\n\nOnce complete, your connection will transcend physical space and make you stronger in more than mere brawn.", progress = "Take your time. This is a significant step in your journey to ascension.", completion = "Your journey together is just beginning.", objectives = "Complete the soulbinding ritual.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57899] = { id = 57899, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Work?", description = "Your world has a saying that \"you cannot be in two places at once.\"\n\nWithout a soulbind, that is true. Thankfully we have resolved that matter. Such physical limitations are a mortal construct.\n\nChristen our newest addition to the Hold in the ramparts above, then seek out Koros and you will see.", completion = "I am Koros, head communicator of the hold. A pleasure.", objectives = "Activate the Command Table.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57900] = { id = 57900, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Across the Shadowlands", description = "As kyrian we are responsible for ensuring that every last soul that enters the Shadowlands is sent to their appropriate eternity.\n\nHowever, our eternal charge does not end in Oribos.\n\nThere are countless matters in the Shadowlands that need attention--far more than any one of us can handle. That, my friend, is where I come in.\n\nConsider me your eyes in the field. Allow me to demonstrate with a simple task, so that you may both reap the benefits of my services.", progress = "Good things are worth waiting for.", completion = "You see, my mortal friend, it truly is that simple!", objectives = "Use the Command Table to start an adventure.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57901] = { id = 57901, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "All That Remains", description = "Just as you must work with your soulbind in an eternal partnership to ensure peace in our realm, so must you work to restore the flow of anima in the sky above.\n\nCapheus, one of the great Mikanikos's students, has specialized in the craft of directing what anima we have to the temples that need it most.\n\nGiven the great drought of anima that plagues us if anyone could use assistance, it would be her.", progress = "Yes, yes, you! You can help!", completion = "The others speak of you! Come! Let me know you too!", objectives = "Activate the Anima Conductor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57903] = { id = 57903, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Power in the Sky", description = "This device you see here can be used to send anima to our temples and aid our people.\n\nAs each temple regains its flow of anima, it will begin to function once more. You may find these functions useful in your journeys, or you may even find new challenges that await you.\n\nOnce you have brought some anima to our sanctum, use the device to direct it to a temple, and see the results for yourself.", progress = "Does the anima flow?", completion = "Good, anima is flowing again. You will want to return to the device periodically and channel more anima.\n\nAs you gather more anima and channel it into Bastion, the flows will grow stronger. Though they will not last for long right now, eventually you will be able to reinforce the channel, making a permanent connection.\n\nOnce, the skies of Bastion were alight with the flows of anima. With your help, they will be again.", objectives = "Use the Anima Conductor to channel anima to a location in Bastion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57904] = { id = 57904, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Our Eternal Charge", description = "You have been fully inducted into our sacred covenant, Maw Walker, and may stand tall forevermore as a kyrian. There will be many challenges ahead of us--we shall face them together.\n\nFor now, return to Polemarch Adrestes and inform him that your training is complete. We are few in number as of late and I am sure he will have need of you. \n\nGo in service, {name}.", completion = "On behalf of our glorious Archon, may you follow the path always towards a brighter tomorrow.", objectives = "Return to Polemarch Adrestes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57905] = { id = 57905, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Unique Opportunity", description = "All the anima in the Shadowlands will not restore Elysian Hold to its full glory without willing souls to ensure its many capabilities function properly.\n\nSoulguide Daelia is one of our most veteran watchers. She has been tasked with bringing souls to these halls once more.\n\nYou should pay her a visit within the Sanctum of Binding to see if you might be of aid.", completion = "Your arrival is most timely, Maw Walker.", objectives = "Speak to Soulguide Daelia in the Sanctum of Binding.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57908] = { id = 57908, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The True Crucible Awaits", description = "I confess, {name}. I had little hope when you first arrived.\n\nKleia is convinced that your presence here is a sign of things finally improving in Bastion. I was... skeptical.\n\n<The Forgelite gestures to her forge.>\n\nWhat you have done for me will not soon be forgotten. There is a path beyond the Crucible. To walk it, you must overcome a trial. It will be difficult. Such a thing takes eons for most.\n\nYou are not most.\n\nKleia and Pelagos will tell you more. They await you near the sparring grounds.", completion = "The Forgelite's gratitude goes deeper than you know.\n\nNow. You must turn your attention back to our purpose here.", objectives = "Speak to Kleia and Pelagos in Aspirant's Crucible.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57909] = { id = 57909, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assessing Your Stamina", description = "The trial ahead will test you on many levels. I, like Kleia, wish to assess your willingness to endure.\n\nLook around you. All the aspirants here train for the very trial you are to attempt. Some have been here, honing their skills, for centuries. Ages. Some grow quickly, some do not.\n\nYour task is to engage them in friendly, armed combat. Among the kyrian this is known as a combat meditation.\n\nHelp them find focus, and they shall help you do the same.\n\nReturn to me when you feel ready to continue.", progress = "Trust in the process, {name}.", completion = "To fight so many, in so short a time, is truly a feat of stamina.\n\nI am tired just looking at you.\n\n<Pelagos laughs.>", objectives = "Participate in 8 combat meditations.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57912] = { id = 57912, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Baron of the Chosen", description = "Our forces at the Spearhead are under siege from Margrave Gharmal's vanguard. If Vyraz himself is leading the defense, then the situation must be dire.\n\nThe House of Constructs shapes flesh to forge bodies for its forces. They were once an indispensable ally, but have become a fearsome enemy.\n\nMargrave Krexus trusts your might. No doubt you will have need of it.", completion = "I expect much of you, mortal. Help lead our frontal assault on the construct forces!", objectives = "Meet with Baron Vyraz at the Spearhead.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57914] = { id = 57914, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mark of Knowledge", description = "There is another matter for which I need your assistance. My researchers and interrogators have been tirelessly working on the second chamber. So far they don't have any leads.\n\nI need you to speak to them and see if they've made any progress. Tell them, if they have nothing to show, then they will soon find themselves at the end of my sword.\n\nGet me that mark, quartermaster!", progress = "Did you bring the mark? If not, then why are we speaking?", completion = "One step closer to my goal.", objectives = "Obtain the Mark of Knowledge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57915] = { id = 57915, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Search for Survivors", description = "The bugs came from everywhere... There wasn't any time to react.\n\nMany of my friends died where they stood, while others tried to fight with our meager tools.\n\nI'm a coward. I fled in the commotion instead of trying to help.\n\nNow, here I am, out of food and water and too scared to look for survivors.\n\nPlease, I beg you to help anyone you find left alive in Orsis...", completion = "I am in no shape to face those creatures right now. I appreciate your help {name}.", objectives = "Check 8 Wastewanders in Orsis.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57918] = { id = 57918, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Absolution of Souls", description = "Do you not yet understand the purpose of Revendreth, Maw Walker?\n\nThe souls under our care teeter on the brink of permanent damnation. Even with perfect attention and careful processing, not every soul can escape the Maw and be elevated to a higher destiny.\n\nThat is true under the best of circumstances.\n\nCurrently, due to your installation of the Chamberlain at the Halls of Atonement, we're instead witnessing the worst of circumstances.\n\nWe must return to the Halls of Atonement and enforce order.", completion = "It is worse than I feared.", objectives = "Meet the Accuser at Absolution Crypt.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57919] = { id = 57919, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Abuse of Power", description = "The souls have suffered tremendously under the Lord Chamberlain.\n\nWe venthyr subjugate souls to our will so that we may lead each to the absolution it requires--willing or not.\n\nThe Lord Chamberlain, however, has been using our relics and rituals to abuse the souls under his authority. He binds the souls to their sinstones, perverting their very essence!\n\nUse these ritual chains on the abused soul and subjugate it to your will. We must attempt to absolve it.", progress = "Every lost soul is a tragedy.", completion = "That soul is now lost forever. Such wasted potential...\n\nThe Lord Chamberlain will answer for this offense.", objectives = "Subjugate the Abused Soul.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57920] = { id = 57920, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Proper Souls", description = "We must save as many souls as we can from the fate we have just witnessed.\n\nSearch the halls for souls who have escaped the Lord Chamberlain's perverse rituals. Subjugate them and bring them to me inside the Halls of Atonement.\n\nTogether, we will make certain that each soul is appropriately processed and cared for.", progress = "If even one soul can be saved, it is worth it.", completion = "Every lost soul must be tended to.", objectives = "Subjugate 4 Fugitive Souls and deliver them to the Accuser.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57921] = { id = 57921, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Proper Tools", description = "There are very specific procedures that we must follow to best tend to the souls under our care. You and I will follow them exactly.\n\nI can mask your garish appearance, but you must acquire the necessary ritual tools on your own.\n\nRequisition them from the depraved venthyr serving the Lord Chamberlain nearby.", progress = "We will do this the proper way.", completion = "Good. You are ready for the ritual.", objectives = "Collect Venthyr Ritual Robes, Dagger, and Tome.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57922] = { id = 57922, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Proper Punishment", description = "Thankfully, I am not the only one who remembers the high calling of the Halls of Atonement and its servants.\n\nThese avowed ritualists have been working covertly to preserve the integrity of the halls.\n\nThey report that the Lord Chamberlain relies on a particularly gifted soulflayer to teach other ritualists how to corrupt the souls.\n\nGive him the reward he deserves.", completion = "His just reward would be the Maw, but this will have to do.", objectives = "Kill Fata the Soulflayer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57923] = { id = 57923, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ritual of Absolution", description = "The ritual of absolution is a sacred rite that forces souls to discard the burdens of their mortal lives.\n\nThe soul must be a willing participant if the ritual's effect will be meaningful and long-lasting. We often spend ages preparing a soul for a single absolution ritual.\n\nThe Lord Chamberlain has neglected his duty. These souls are overdue for absolution, practically bursting with anima.\n\nWe will perform the ritual ourselves, and hurry these souls along their journey.", progress = "Absolution is where mercy meets justice.", completion = "Absolution does not come easy. Nor should it.", objectives = "Help the Accuser complete the ritual of absolution.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57924] = { id = 57924, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ritual of Judgment", description = "After all rituals of absolution are complete, each soul must face its final judgment in Revendreth.\n\nThere are three potential verdicts:\nIf proven unworthy, it is condemned to the Maw for eternity.\n\nIf fully absolved of its sins, it is either elevated to a venthyr or returned to the Arbiter to be assigned its new destination.\n\nOur most sacred ritual, the judgment, determines this fate.\n\nOne such ritual is happening now. I will disguise you and we will participate to ensure a just verdict.", completion = "I sacrificed more than you realize to save this soul.\n\nI would do it again, because it is right. Do you understand yet?", objectives = "Participate in the ritual of judgment.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57925] = { id = 57925, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Archivist Fane", description = "Well, our disguises are superfluous now. We will not be welcome after disrupting their depraved ritual.\n\nDespite what we've observed here, some steadfast venthyr do still remain within these halls. Those who have not forsaken our vocation, and carry on with our calling.\n\nArchivist Fane is one such as these. Aid his endeavors however you can. We will need his insight to loosen the Lord Chamberlain's grip over these halls.\n\nI must tend to Gresit. He has much to learn.", completion = "Some very angry judges recently passed through here.\n\n<Archivist Fane grins.>\n\nTell me everything you did to antagonize them. Don't skip a single detail!", objectives = "Introduce yourself to Archivist Fane.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57926] = { id = 57926, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sinstone Archive", description = "You said Inquisitor Traian oversaw the ritual?\n\n<Archivist Fane searches the massive archives in this chamber.>\n\nWe archivists maintain strict records of every soul that passes through these halls.\n\nOr at least we're supposed to. The sinstones of powerful venthyr tend to go \"missing.\"\n\n<Archivist Fane rolls his eyes.>\n\nI don't see his sinstone here. He might've stolen it, or someone could be hoarding it as blackmail.\n\nHelp me complete my archives, and I'll get you any sinstone you need.", progress = "Sinstones are the most powerful weapon in Revendreth.", completion = "<Archivist Fane's eyes light up when you hand him the archives.>\n\nThis is a lot of potential leverage...", objectives = "Collect 100 Sinstone Records.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57927] = { id = 57927, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rebuilding Temel", description = "Revendreth demands penance from all, and it would appear that even you are not exempt.\n\n<Cryptkeeper Kassir grins.>\n\nDo not fear, I have no intention of exacting revenge for the violence you inflicted upon me.\n\nBut I cannot offer you Temel either.\n\nThe Lord Chamberlain--who you so wisely chose to install as master of these halls--deemed Temel a threat to his control.\n\nHis thugs bashed Temel to bits and scattered the pieces among these crypts. It's not the first time I've had to rebuild him.", progress = "No matter how broken Temel is, I can rebuild him.", completion = "<Cryptkeeper Kassir inspects the pieces of Temel you brought him.>\n\nThey bashed you real good, didn't they, Temel? Nothing I cannot fix...", objectives = "Collect Temel's Head, Body, and Wings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57928] = { id = 57928, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Atonement Crypt Key", description = "<This key is marked with a sigil that matches the crypts in the Halls of Atonement. What is the Lord Chamberlain hiding away in there?>", completion = "The atonement crypts are meant to be used as storage for souls who require additional... processing before their next ritual.\n\nThe Lord Chamberlain's idiots are using them like prison cells and treasure rooms. You are doing us all a favor by opening them whenever you find a key.", objectives = "Open an Atonement Crypt.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57929] = { id = 57929, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hunting an Inquisitor", description = "You may have noticed that inquisitors are protected by the Lord Chamberlain's magic. A potent consequence of wielding the Master's medallion.\n\nBut now that we have access to Inquisitor Traian's sinstone from the archives, we have the power needed to break through those defenses.\n\nLocate the inquisitor, and order Temel to read out from his sinstone. Declaring the true name and sins of the inquisitor will shatter his defenses and make him vulnerable for a short window of time.\n\nBe ready to strike.", progress = "Truth, wielded properly, is a potent weapon.", completion = "Decorous and deserved.\n\nI hope this will be the first of many corrupt inquisitors we fell together.", objectives = "Kill Inquisitor Traian.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57931] = { id = 57931, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Phalynx Malfunction", description = "As part of their training, I order my phalynx units to march the fields, keeping an eye on the wildlife and any goings-on.\n\nUnfortunately, last time they returned they were one fewer in number.\n\nPlease search the Golden Pasture and search for the missing unit, then return it here.", progress = "My phalynx units require occasional repairs to keep them operational. If one is overlooked, it may malfunction.", completion = "This unit seems to be malfunctioning. We will have to perform some repairs.", objectives = "Find Gatamatos in the Golden Pasture and return him to his pedestal in Forgefire Outpost.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57932] = { id = 57932, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Resource Drain", description = "Usually repairs easy. Anima everywhere!\n\nExcept drought means we can't just pull it from air. Other sources needed!\n\nTake this. Drain anima from cloudstriders. Not ideal, but desperate times.", progress = "Drought has big effects. Feel bad for cloudstriders.", completion = "This is enough to repair Gatamatos, and then some!", objectives = "Drain anima from Gilded Cloudstriders 5 times.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57933] = { id = 57933, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We Can Rebuild Him", description = "Gatamatos needs numerous repairs to meet functional standards.\n\nUpkeeping phalynx is part of the role. Lend a hand so we may finish the repairs thoroughly and quickly.", progress = "As long as you keep your phalynx in working condition, they will obey without hesitation.", completion = "He may appear to be returned to perfect shape, but he must be re-tested and trained.", objectives = "Aid Pelodis in repairing Gatamatos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57934] = { id = 57934, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Combat Drills", description = "Our phalynx units excel in combat. They are thoroughly trained in taking foes down by the legs, as well as hunting down beasts gone awry.\n\nI need you to take stock of Gatamatos's fighting routines. Take him into the cavern below and practice his combat against the wyrms there.", completion = "Excellent. His combat routines are acceptable.", objectives = "Kill 8 Agitated Etherwyrms in the Hall of Beasts with Gatamatos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57935] = { id = 57935, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Laser Location", description = "Phalynx have precise detection mechanisms that allow for excellent scouting.\n\nIn the cave below we have scattered gems that our units are trained to locate. Escort Gatamatos to run some drills and recalibrate his training.", progress = "The technical process behind phalynx tracking and locating their targets is quite fascinating.\n\nHowever... you do not seem the type who is interested in the details.", completion = "I would like to see a larion track that accurately!", objectives = "Bring Gatamatos to the Hall of Beasts, then direct him to locate 6 Training Gems.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57936] = { id = 57936, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Superior Programming", description = "Phalynx listen to their orders. Never disobey!\n\nLarions are wild beasts. Can attack. Could eat a steward, probably!\n\nUntamed larion lives close. Has chased many stewards, very scary! Please take care of it.", progress = "Wild beasts. Terrifying! No thank you! I work with very safe phalynx.", completion = "Can be at peace, no wild larion to eat me. Hoo...", objectives = "Kill Leonid in the Hall of Beasts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57937] = { id = 57937, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tactical Formation", description = "The principal step of our training regiment for our phalynx is formational drills. They must recall standard kyrian battle formations, and how to flow from one to the next.\n\nFormational training is the final piece of information that Gatamatos is still missing. Please aid in retraining him.", progress = "A good soldier marches in order.", completion = "And with that, I believe that Gatamatos is once again functioning at standard.\n\nThank you for your aid.", objectives = "Aid Gatamatos in taking the correct position in three formations.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57947] = { id = 57947, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spirits of the Glen", description = "Animals of the forest, mortal souls given form, frolic in the glen. Their anima, a boon to the weald, given freely as rain on the leaves.\n\nBut danger lurks in the shadows. A dark storm of malice and enmity tears at the trees. Creatures seeking shelter find only peril.\n\nRescue them.", completion = "What's this? What's this?\n\nThe Tall Tree has sent you to help us? Help us!", objectives = "Find Choofa in the Spirit Glen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57948] = { id = 57948, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nothing Left to Give", description = "Oh no, oh no!\n\nMy friends, they gave so much. So much of their anima, they lost their forms! We all take a form when we come here, you see. Something that suits us!\n\nBut we give our anima, we give! To help the groves. And we give so much... sometimes too much.\n\nI still have some anima. I still have my form! Get me to my friends! We can get THEIR forms back!", progress = "Oh dear, oh dear. My friends are in trouble!", completion = "You found them! You found my friends! They have their forms!\n\nNow we have one last thing to do. One last thing!", objectives = "Restore soul shapes to Slanknen, Rury, and Awool in the Spirit Glen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57949] = { id = 57949, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "They Need to Calm Down", description = "Spriggans! Nasty spriggans. They came to the grove. They messed it all up!\n\nThey took the anima from the soul webs! We were collecting it, yes. Collecting it for the Tall Tree and their grove. The spriggans have to pay!\n\nBeat them up! Then use this soulweb to take back the anima. We need it! They don't!", progress = "Did you destroy them? Did you make them pay?", completion = "Stolen! They stole the anima! They ran like crazy and...\n\nWait that's normal. They're always that bad. Stupid spriggans!", objectives = "Defeat Spriggans and use the Soulweb to drain them of stolen anima in Spirit Glen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57950] = { id = 57950, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mizik the Haughty", description = "Bad spriggans! Bad! They take our anima. We lose our forms! And one is worst of all.\n\nMizik! He tells the others what to do. And he rides a gorm! Big, nasty gorm!\n\nGet him. Get him!", completion = "Gone! The bad spriggan is gone! Spirit Glen will be ours again.\n\nNow to leave. We have to leave.", objectives = "Defeat Mizik the Haughty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57951] = { id = 57951, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Souls Come Home", description = "To the tree, to the tree! It is time for us to return to the grove.\n\nWe have our anima. We have our forms. The Tall Tree needs the anima. The Tall Tree will be happy!\n\nI will see you there!", completion = "From acorns grow forests, from souls comes vital anima. Small though they be, on them our fates depend.\n\nThe forest sighs in gratitude.", objectives = "Report your success to Droman Tashmur in Tirna Vaal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57952] = { id = 57952, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Need of Gorm Gris", description = "Our neighboring grove at Glitterfall Basin has sent out a desperate plea for gorm gris.\n\nIt may have humble origins, but it is an important ingredient for our artisans and crafters. As this drought goes on, it has become increasingly difficult to collect.\n\nI would like to help them out, with the resources that we are able to spare.\n\nPlease, find Master Sha'lor out by the Tranquil Pools, where he keeps our little gormling population.\n\nAsk him for more gorm gris.", completion = "Kota has asked for gorm gris?\n\n<Master Sha'lor beams with excitement.>\n\nI would be happy to oblige her request! Come, let me show you how this works.", objectives = "Seek out Master Sha'lor by the Tranquil Pools.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57954] = { id = 57954, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Burn the Bodies", description = "The bugs seem to be indiscriminately laying eggs all over the nearby corpses.\n\nThey are using them as food to spawn more of those horrible things. Disgusting!\n\nWe can mourn the dead later, but if any more bugs are allowed to hatch we may not live long enough to do so.\n\nBurn the bodies and destroy those eggs!", completion = "Grisly work to be sure, but we were left with no choice. Thank you {name}.", objectives = "Burn 10 Egg-bearing corpses.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57955] = { id = 57955, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Ankhaten Harbor", description = "I fear that I don't yet have the strength to ride out into the sands and face those monsters again.\n\nRide to the south and find Tracker Samara in the excavation camp formerly known as Schnottz's Landing.\n\nTell her to halt any caravans that plan to pass this way, lest others are ambushed and met with the same grisly fate.\n\nWe must get the word out across Uldum before our forces are further divided!", completion = "Orsis is lost you say!? This is truly worse than I feared.", objectives = "Find Tracker Samara in Ankhaten Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57956] = { id = 57956, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wastewander Hosts", description = "The bugs have been laying eggs in the corpses of our soldiers, it's absolutely terrifying!\n\nSome of them are rising from the ground as putrid, bloated, hideous monstrosities.\n\nWe have to stop them before they continue to bolster their ranks with our fallen.\n\nIt's not a pleasant task... but I have to ask you to help me destroy them. Completely.\n\nGrab some bombs behind me, if you'd like.", completion = "Blech. I can clearly see that you killed them all, thank you for bringing back that truly awful smell.", objectives = "Kill 6 Wastewander Hosts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57959] = { id = 57959, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heroic Warfront: The Battle for Darkshore", description = "Darkshore belongs to the Horde! We must hold that ground to maintain our dominance over Kalimdor.\n\nPrepare yourselves. Battle awaits!", completion = "Well fought, {name}, though I'm sure it won't be long before the Alliance try to reclaim Darkshore. When they do, we will be ready to fight!", objectives = "Defeat the Alliance at the Battle for Darkshore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57960] = { id = 57960, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heroic Warfront: The Battle for Darkshore", description = "We will not tolerate further Horde aggression in our territories.\n\nThe night elves will not stand alone this day. Darkshore will be theirs once more.\n\nFor the Alliance!", completion = "The day is ours thanks to you, but this war is far from over.\n\nFor the Alliance!", objectives = "Defeat the Horde at the Battle for Darkshore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57961] = { id = 57961, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heroic: Battle for Darkshore" }
quests[57962] = { id = 57962, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heroic: Battle for Darkshore" }
quests[57964] = { id = 57964, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Revenge Is Easy", description = "There's still a lot of us here, trying to survive in these ruins.\n\nThese constructs have been encroaching on us constantly. They steal what they can, and haul off any of us they capture to be recycled in their labs.\n\nThe solution here requires an extensive use of violence, by you!", progress = "I still see a lot of abominations walking around.", completion = "You can kill more of them if you want.", objectives = "Kill 15 bonefused forces.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57966] = { id = 57966, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You Go First", description = "You've proven useful. So, I am going to require you to disarm the defenses of this hall. \n\nPlease take care not to die too quickly. I'd like to have the spear before the end of this eon.", progress = "Continue to be of use and you just might make it out of this intact.", completion = "Your efforts have brought me what I desire. For your reward, I won't kill you.", objectives = "Disarm the traps within the Third Chamber of Kalliope and make your way to the final hall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57967] = { id = 57967, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rightful Resting Place", description = "You have truly proven yourself a hero in the eyes of those who are its absolute judge.\n\nI thank you for giving me the honor of holding it, even for this briefest moment. However, it is only proper that you be the one to enshrine the spear at it's rightful resting place.\n\nLet us meet at Elysian Hold where you can do the honors.", progress = "<The resting place of the spear lies before you.>", completion = "<Place the Spear of Kalliope in its rightful place knowing that only a true hero can do so.>", objectives = "Enshrine the Spear of Kalliope in its rightful place at Elysian Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57968] = { id = 57968, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Wastewandering Dead", description = "Is there no end to these foul monsters!?\n\nI cannot abide the desecration of our dead, especially not as fodder for this disgusting insect army.\n\nDestroy as many as you can, preferably with fire!", progress = "I hope you've been keeping count of your kills.", completion = "There is just no end to them...", objectives = "Kill 6 Wastewander Hosts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57969] = { id = 57969, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tend the Wounded", description = "My friend, as you can see here, we are besieged by these terrible creatures.\n\nMany of our comrades have fallen prey to the monsters, but fortunately, we have enough warriors here to keep the threat at bay... for now.\n\nIf you are able to assist us, please, tend to our wounded and help clear a path for them to escape the ruins.", completion = "You are a true hero, my friend.", objectives = "Heal 8 Wastewander Laborers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57970] = { id = 57970, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruinator Xok'nixx", description = "Ar'kali and a group of our warriors are engaged with a most behemothic creature in the heart of the ruins.\n\nShe can hold her own against nearly any foe, but I fear it is only a matter of time before this monster is able to wear them down.\n\nAlthough the creature is occupied for now, if our warriors fall, the ruins will be lost to us.\n\nPlease, make haste, with your help they can surely fell this titanic foe.", completion = "You are a capable fighter. Thank you for assisting our warriors!", objectives = "Kill Ruinator Xok'nixx.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57971] = { id = 57971, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruins of Ammon", completion = "Seeing you here is like stumbling across an oasis in the desert, my friend!", objectives = "Travel to the Ruins of Ammon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57973] = { id = 57973, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heroic: Battle for Darkshore" }
quests[57974] = { id = 57974, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heroic: Battle for Darkshore" }
quests[57976] = { id = 57976, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lead By Example", description = "Margrave Krexus expects much of you, mortal. Show these soldiers how a true champion of the arena vanquishes their foes and claims victory!\n\nMeet these traitorous constructs head on. Leave none standing!", progress = "What?", completion = "That should strike fear into their stolen hearts.", objectives = "Kill 12 Steelskin Vanguard or Steelskin Brutalizers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57977] = { id = 57977, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Temple in Need", description = "<Eridia peers down at you.>\n\nYour face is new to me.\n\n<Eridia frowns.>\n\nI regret that this shall be your introduction to our temple. As my disciple has informed you, we seek the aid of all available aspirants to tend to those in our care.\n\nDo not trouble yourself over the specifics of the work that is needed. Those devoted to this temple will guide you. Seek out the disciples within.\n\nYou may find me within the temple when you have given your aid.", progress = "Have you lent my disciples your aid?", completion = "You have proven yourself adept at this task. You have my gratitude.", objectives = "Aid the disciples within the Temple of Purity.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57979] = { id = 57979, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Offensive Behavior", completion = "Your leadership is inspiring. These troops would follow you anywhere!", objectives = "Kill General Alver.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57982] = { id = 57982, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breaking Down Barriers", description = "As I suspected, Stitchflesh's assistants are carrying on his work. Whatever they're building, we need to destroy it.\n\nThey've secured the chamber with a soul barrier and several bile spewers. We must find a way through!\n\nThales said he may have a suggestion.", progress = "Is the barrier down?", completion = "It seems these kyrian are more stalwart than I expected. Let us avenge their fallen kin.", objectives = "Find a way past the Soul Barrier.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57983] = { id = 57983, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Archon Save Us", description = "Most of the aspirants were slaughtered and dismembered on arrival. They were the lucky ones. \n\nThe lead surgeon decided that the only things worth taking from me... were my eyes. I was discarded afterward and left to my rot. Archon save me, the screaming...\n\nI think there are other survivors being held nearby. Can you aid me in freeing them?", progress = "Yes?", completion = "Only four survivors... I know I should be grateful that there were any at all, but...\n\nWhat sort of monsters would do this to anyone, let alone to their own people?", objectives = "Save the souls in the Holding Pens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57984] = { id = 57984, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ones in Charge", description = "They have been collecting kyrian... and our corpses... for some dark purpose.\n\nWhatever they are planning, we must put a stop to it.\n\nI have overheard mention of three individuals who seem to be in charge. We need to find them and eliminate them.", completion = "It seems one of the house's barons is overseeing this operation... and he is unaware that we are free. \n\nWe have a chance to strike him down!", objectives = "Slay Doctor Hivvil, Tabulator Hymeris, and Leacher Cvan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57985] = { id = 57985, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Give Them a Hand", description = "The corpses are brought to this pit for processing. Their flesh is liquified and congealed before being shaped into new constructs.\n\nWe can hinder their production by extracting the animates from the pool prematurely. Use this hook to do so.\n\nDo not let Baron Halis catch you. He has a reputation for cruelty, even within his own house.", progress = "The weak make way for the strong, such is the way of Maldraxxus.", completion = "Slowing the production of new constructs should earn our soldiers some reprieve, however brief.", objectives = "Destroy 10 Vestigial Animates.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57986] = { id = 57986, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Burden Worth Bearing", description = "Mevix may be here for blood, but what I want is to spare my fallen kin from a terrible fate.\n\nMost of my fellow kyrian were either slain in combat or shortly after arriving here. If their corpses were bound for this pit, then perhaps we can recover them before they are thrown into it.\n\nTake the stewards with you and gather the bodies of my brethren. I will not allow them to be made into monsters.", progress = "Were there any left?", completion = "Thank you, {name}. Though they are lost, at least their remains will not be defiled.", objectives = "Help Kou and Koa retrieve 6 Lost Kyrian.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57987] = { id = 57987, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Deadly Distraction", description = "Vyraz's assault on the House of Constructs may have failed, but we can still make them bleed now that we're inside.\n\nSlaughter as many as you can. I will hunt down the masterminds behind these new production efforts.", completion = "Complacency is every soldier's worst enemy. No one is safe in times of war, not even within the walls of their own fortress.", objectives = "15 Warstitched forces slain.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57989] = { id = 57989, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Spear of Kalliope", description = "The Spear of Kalliope is finally in my grasp!\n\nWith it, I will lay waste to all the Forsworn's enemies. Now behold while I take my prize!", progress = "Did you find the spear?", completion = "The spear! You've saved it from the hands of the Forsworn.", objectives = "Defeat Artificer Ligiea and earn the Spear of Kalliope.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57990] = { id = 57990, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Obelisk of the Sun", description = "I have one more thing I must ask of you, my friend. Completion of this task is critical to our survival here.\n\nOur comrade, Zahra, has taken it upon herself to climb the plateau just east of us to secure one of the old bombers left up there.\n\nSo far, our attempts to get word back to Arik have failed. \n\nHowever, if you can help her get one of those planes working, we might just have a chance.\n\nHopefully they can send aid before we are overrun...", completion = "Old man Dyrin sent you, 'eh? Well, I'm glad to have your assistance.", objectives = "Locate Exterminator Zahra at the Obelisk of the Sun.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57993] = { id = 57993, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Two of Them, Two of Us", completion = "I sense something within this construct... something familiar...", objectives = "Defeat Sharrex the Fleshcrafter and First Apprentice Malkrex.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57994] = { id = 57994, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In The Flesh", description = "The souls of the fallen kyrian... I can sense their pain and confusion. They yet exist within the construct!\n\nPlease, we must not destroy it. Doing so would consign the souls within it--the souls of my brethren--to oblivion. \n\nPerhaps... perhaps they can aid us in escaping to freedom. I will soothe the souls within the construct while you direct its actions.", progress = "My fallen kin...", completion = "We escaped!\n\nWe will recuperate here for now. At least until we find a way to return to Bastion.\n\nThank you for showing me what courage is, my friend.", objectives = "Take control of the Soulfused Construct and escape the House of Constructs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58007] = { id = 58007, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eyes on the Problem", description = "Our enemies rally at our gates. We cannot rely on daring air strikes to hold them at bay.\n\nVashj has a plan to permanently bolster our defenses. With your help, it might actually succeed.\n\nDo what you can to assist her. She seems more... agreeable toward you than she is with me.", completion = "Our foes will regret opposing us.", objectives = "Speak with Vashj and put her plan into action.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58008] = { id = 58008, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "All Gassed Up", description = "So, I was checkin' all these planes... and you are never gonna believe this, but none of them have any fuel in the tanks!\n\nSaw a few canisters scattered around nearby, surely some a' them have some gas left.\n\nWas gonna collect 'em myself, but these damned bugs came outta nowhere and started swarmin' the place.\n\nToo many here now to deal with on my own, think you'd be able to lend a hand?", progress = "Yo, you got them fuel cans yet?", completion = "Well hot damn, you did great finding all of these!", objectives = "Collect 6 Fuel Canisters.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58009] = { id = 58009, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Moon", description = "Alright! It's time to high tail it outta here.\n\nWe gotta get back to camp and tell Arik what's been going on out here as soon as possible.\n\nHead for the bomber and let's fuel 'er up. \n\nI'll letcha have the gunner seat, but I'm drivin', so let's try to blow up a few bugs on the way back!", completion = "What in the blazing sands were you doing up there!?", objectives = "Remove the Aqir threat from Obelisk of the Moon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58010] = { id = 58010, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Bits, More Bits!", progress = "Have you obtained any additional samples?", completion = "Excellent, thank you for collecting these samples.", objectives = "Collect 16 Aqir Bits.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58011] = { id = 58011, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bug Bites", description = "Margrave Stradama eagerly awaits the completion of our latest potion!\n\nHowever, I seem to have misplaced my stockpile of venom sacs. How embarrassing! I have felt a touch out of sorts lately...\n\nWould you please do me a favor and fetch some more? We cannot continue our work without them!", progress = "Now where did I put my venom sacs...", completion = "You found my venom sacs! What a helpful apprentice you are!", objectives = "Collect 6 Bloated Venom Sacs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58016] = { id = 58016, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spores Galore", description = "My brightest apprentice, you return to me at last!\n\nYou worried me--you see, I heard the loudest clatter while working on one of my experiments... Before I knew it, I was here, and you'd disappeared!\n\nWherever you went is no matter. You're back now, and we have much to do!\n\nCome, my apprentice--we must fetch our ingredients first.\n\nCan you smell the spores germinating around us? We should pull some up to use in our endeavors!", completion = "Such marvelous spores, my apprentice!", objectives = "Harvest 8 Stringy Spores.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58022] = { id = 58022, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finish What He Started", description = "Finding Sha'lor is our main priority. But there is another opportunity.\n\nTake the Gormherd Branch that he dropped. I know he was tinkering with it so that it would work on wild gorm.\n\nUse it on the gorm in the burrows, and see if you can collect any of their gorm gris.\n\nDon't bother with the little ones; get the really potent stuff from the bigger gorm.\n\nPerhaps if we can collect enough, and find that silly sylvar, he will not rush horns-first into the burrows again.", progress = "Have you had any luck?", completion = "Well done. You've collected enough gorm gris to hopefully keep Sha'lor from venturing into the burrows all by himself, again.\n\nAnd we should be able to send some to our friends in Glitterfall, once all this is over. \n\nThank you.", objectives = "Use the Gormherd Branch to collect Wild Gorm Gris from gorm in the Dusty Burrows.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58023] = { id = 58023, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One Big Problem", description = "We must go after Master Sha'lor. Tirna Vaal needs him! And I... I...\n\nI will report to the droman. They must know that Sha'lor is in danger. Then, I will enter the burrows myself from the south and help you defeat it.\n\nFor now, see what you can find. I refuse to believe that he is gone.\n\nThat monster will know the fury of a vorkai.", progress = "What's gotten into these gorm?", completion = "Well done. You drove the beast hard enough that she spat out Sha'lor. Now she hides in her den.\n\nShe has nowhere else to run.\n\nNow we end this.", objectives = "Hunt down the Gorm Matriarch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58024] = { id = 58024, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Burrows Away", description = "<The ground has been freshly dug, and there are signs of more tunnels all over the place.\n\nCollapsing a few burrows would go a long way toward keeping Tirna Vaal safe from gorm infestation.>", completion = "The gorm are digging even MORE burrows beneath Ardenweald? This is very bad news indeed. \n\nThank you for taking it upon yourself to close them down. That should give us some time to reinforce our defenses.", objectives = "Collapse Gorm Burrows in the Dusty Burrows.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58025] = { id = 58025, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Queen of the Underground", description = "You tracked the massive gorm here to her den, and we've found Master Sha'lor.\n\nPerhaps not entirely unscathed, but he lives. That is enough.\n\nOne last task remains. Let us end this.", progress = "Tirna Vaal will not be safe with that monstrosity about.", completion = "How is that possible? The matriarch she... they feasted on the pods. What if there are others like her out there in Ardenweald?\n\nWe must report this immediately.", objectives = "Slay the Gorm Matriarch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58026] = { id = 58026, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "When a Gorm Eats a God", description = "There is nothing more we can do here. I will get Master Sha'lor safely back to Tirna Vaal.\n\nWhen you get there, report to the droman what we found here. \n\nIf the gorm have started to eat the dead wildseeds, and are absorbing the power of the spirits within, we are all in serious danger.", completion = "Those that speak, think. A different kind of Queen is born.\n\nThe forest worries. For this will surely not be the last.", objectives = "Report back to Droman Tashmur in Tirna Vaal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58027] = { id = 58027, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Slime, Anyone?", description = "While I know we're both eager to complete our potion, I believe the best lesson I can share with you is patience.\n\nPatience and slimes, of course!\n\nWith the help of slimes, we'll have our laboratory back in working condition. It's just as I taught you: combine your ingredients in the cauldron. Mix until the viscosity is just right...\n\nOh, listen to me--acting as if you've never concocted your own sentient being!\n\nGo on, my apprentice! The slimes are calling!", progress = "Go on, now! You can do it!", completion = "What a precious slime!", objectives = "Craft a Plagueborn Slime in Marileth's cauldron.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58031] = { id = 58031, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Applied Science", description = "<What appears to be an old journal sits on Marileth's table, now mangled and missing pages.\n\nThe entries that are legible seem to have been written by Marileth when he was still sane, before the fall of his house.\n\nPerhaps if you find the journal's missing pages, you will gain more insight into what befell the House of Plagues.>", completion = "Oh--and what are these?", objectives = "Collect the lost pages of Marileth's journal from Plague-doused Remnants.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58036] = { id = 58036, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hazardous Waste Collection", description = "Ah, slimes: the dearest of friends and infinitely useful! They will help us craft our potion.\n\nBut it seems our tools have been scattered around, doused in toxic refuse. Margrave Stradama would be so disappointed at my lack of respect for lab safety!\n\nYour slime can comb through the refuse, diluting the plague's harmful agents. Simply pull the cleaned equipment from the body of your slime!\n\nSlimes... what would we do without them?", progress = "Has your slime been useful? I'm sure it has!", completion = "You and your slime are bonding!", objectives = "Collect 6 pieces of Laboratory Equipment.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58037] = { id = 58037, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Part of the Pride", description = "Pelodis insists that phalynx are superior to all autonomous beings, taking orders without fail.\n\nBut where is the nuance? Where is the reward for your effort?\n\nLarions make fantastic companions, but you must build a relationship with them. Introduce yourself to my pride. You will see that each has a personality of their own.", progress = "Larions are free-thinking beings. They will decide whether you are accepted within the pride.", completion = "My pride is generally wary of newcomers, but they seem to accept your presence.", objectives = "Introduce yourself to 5 Tamed Larions.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58038] = { id = 58038, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "All Natural Chews", description = "A huge part of larion care is providing for them and keeping them happy.\n\nLarions need to keep their teeth sharp and healthy, and for that they need to chew. If you do not give them proper things to chew on, they can get destructive.\n\nOne of their favorite chew toys are the antlers from the cloudstriders in the nearby field. Please, collect some antlers for the pride to enjoy.", progress = "Antlers are great for keeping my pack's teeth sharp and clean.", completion = "The larions will be ecstatic to have more antlers to chew on!", objectives = "Collect 5 Cloudstrider Antlers from Gilded Cloudstriders in the Golden Pasture.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58039] = { id = 58039, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Larion at Large", description = "Some larions are more particular about the people they bond with than others.\n\nLentios is my companion, the larion I trust most with my life. I love the others as well, but he is a part of my soul.\n\nOne of my pride, Andira, has posed a struggle for me to bond with. She ran off into the pastures once again, and I fear she's gotten into something she shouldn't have.\n\nWould you mind finding her and bringing her home?", progress = "Andira and I do not see eye to eye. I know she will be a loyal companion... but perhaps to somebody else.", completion = "Incredible! It seems Andira has taken a liking to you. Perhaps you would be interested in bonding with her further?", objectives = "Find Andira in the Golden Pasture and return her to Nemea's Retreat.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58040] = { id = 58040, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "With Lance and Larion", description = "Say what you want about phalynx, but Larion will always have one major advantage.\n\nWings!\n\nA bonded larion will hunt alongside you whether you are on the ground or in the air. \n\nTake my javelin and Andira then go out into the fields to hunt the cloudfeathers there. You'll feel the boon of larion companionship firsthand!", completion = "It is such a satisfying experience to see your larion take wing to help take down your prey.", objectives = "Kill 5 Cloudfeather Greatwing in Greatwing Roost.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58041] = { id = 58041, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Providing for the Pack", description = "Even beings of the Shadowlands need to eat. They may not do so quite like your world, but it is similar enough.\n\nThe pride's favorite prey is the juvenile cloudfeathers found nearby. Prove to Andira that you are a contributing member of the pride by taking her out to hunt for their next meal.", progress = "Larions bond through hunting. Working together with Andira to collect food is vital to your relationship.", completion = "Providing for the pride is an important step on your path to earning your loyalty here.", objectives = "Collect 10 Cloudfeather Essence.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58042] = { id = 58042, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "On Larion Wings", description = "As a flightless being, you will unfortunately never feel the joy of flying alongside your companion.\n\nHowever... you could still fly with Andira.\n\nIt seems you have earned Andira's trust more than I've seen her with anybody else. Would you like to try a flight course?\n\nTake wing with Andira, then fly through the rings. Don't stray off course or take too much time to get between rings or she will leave you behind!", progress = "I set up the flight course to train the larions to listen to aerial commands. They know where to go!", completion = "The feeling of soaring through the air, the gentle flap of your larion's wings...\n\nEven though I have my own wings, there's no feeling quite like it.", objectives = "Mount Andira, then complete the flight course.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58045] = { id = 58045, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plague is Thicker Than Water", description = "Come closer, my apprentice... I have a mission of dire import!\n\nA necromancer came to our house recently, sent by the lich Margrave Sin'dane! He seemed so polite, always eager to lend a hand in my lady's most volatile creations.\n\nBut I grew wise, my apprentice. The way he skulked around, prodding for our most sensitive experiments...\n\nHe was trying to steal our slimes! I know it!\n\nYou should admonish him quite harshly. Show that no harm will come to our friends!", progress = "Have you chided the defiler?", completion = "Our slimes will be safe, my dear apprentice!", objectives = "Kill Korrim the Cunning.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58060] = { id = 58060, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Night Market", description = "<Dracho motions to keep your voice down.>\n\nI need some assistance, I promise you will be paid handsomely. \n\nAt the edge of The Banewood lies some ruins. These ruins are home to a marketplace run by some brokers. They won't let me back there. Let's just say that my goods were deemed to not be up to their authenticity metrics. \n\nBut you... you're a Maw Walker! Bring them this package and exchange it for some Surberries from Ardenweald. \n\nJust don't say I sent you.", completion = "Ah, Briar Thorn Roses! Excellent. \n\nDon't go just yet. We need to talk.", objectives = "Bring the Hastily Wrapped Package to Ta'ruca at The Night Market in Revendreth.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58062] = { id = 58062, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Very Special Guest", description = "Listen. It is obvious you are doing this deal on Dracho's behalf. \n\nI believe Ta'xera, the boss around here, would be very interested in striking a deal with someone of your talents.\n\nShe resides in the manor at the top of the hill. I recommend you don't keep her waiting.", completion = "I have hoped for your eventual arrival, Maw Walker. \n\nDracho is no longer a partner of ours. Normally we would extend this punishment to you for attempting to subvert our rules. But you being who you are... changes things.\n\nLet's strike a deal. \n\nYou bring things of interest to me directly. No middlemen. No tricks. \n\nWe provide payment and our wares when necessary. Do we have a deal?", objectives = "Speak to Ta'xera at The Night Market.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58068] = { id = 58068, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "...Even The Most Ridiculous Request!", description = "A fan of the competition, are you? Perhaps you would like to be more than a mere spectator?\n\nI will give you a small task... one that not only benefits me, but that also gives you a chance to meet some of the storied competitors here.\n\nAs you can see, our three remaining houses have sent champions to attend the Contest of Conquest. Talk with them and attend to what needs they might have.", progress = "What now?", completion = "We would be so lost without your help. Truly.", objectives = "See to the needs of the Promenade Champions.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58069] = { id = 58069, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Favor: The Venthyr Diaries", description = "This item will be of great interest to the brokers. \n\nPer your previous deal with The Night Market, you should bring it to Ta'xera.\n\nYou will be fairly compensated.", completion = "<Ta'xera perks up at your offer.>\n\nAh, what lies in these pages? \n\nPersonal diary entries it seems. Very interesting. There's even one from the Accuser in here!\n\nThis will be a treat to tear through.", objectives = "Bring The Venthyr Diaries to Ta'xera at The Night Market in Revendreth.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58070] = { id = 58070, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Favor: Soul Hunter Blade", description = "This item will be of great interest to the brokers. \n\nPer your previous deal with The Night Market, you should bring it to Ta'xera.\n\nYou will be fairly compensated.", completion = "What have you brought me today?\n\nOh, I see. The blade from a soul hunter's rapier. This holds great value to those looking to learn more about their dueling techniques. \n\nThank you, {name}. My contacts will be most pleased.", objectives = "Bring the Soul Hunter Blade to Ta'xera at The Night Market in Revendreth.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58071] = { id = 58071, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Favor: Vial of Dredger Muck", description = "This item will be of great interest to the brokers. \n\nPer your previous deal with The Night Market, you should bring it to Ta'xera.\n\nYou will be fairly compensated.", completion = "What is that horrible smell?!\n\n<You present Ta'xera with the vial.>\n\nWell then. While that odor is vile, the contents of that vial are pristine. The very primordial ooze that dredgers are made from.\n\nI'll pay you double whatever anyone else has already offered.", objectives = "Bring the Vial of Dredger Muck to Ta'xera at The Night Market in Revendreth.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58072] = { id = 58072, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Favor: Petrified Stonefiend", description = "This item will be of great interest to the brokers. \n\nPer your previous deal with The Night Market, you should bring it to Ta'xera.\n\nYou will be fairly compensated.", completion = "Is that what I think it is?\n\n<Ta'xera examines the stonefiend closely.>\n\nIn perfect condition! I can't wait to study every intricacy.", objectives = "Bring the Petrified Stonefiend to Ta'xera at The Night Market in Revendreth.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58073] = { id = 58073, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Favor: Portrait of The Sire", description = "This item will be of great interest to the brokers. \n\nPer your previous deal with The Night Market, you should bring it to Ta'xera.\n\nYou will be fairly compensated.", completion = "This is good. You can make out every detail.\n\nMost wonderful find, {name}.", objectives = "Bring the Portrait of The Sire to Ta'xera at The Night Market in Revendreth.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58074] = { id = 58074, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Favor: Ledger of Souls", description = "This item will be of great interest to the brokers. \n\nPer your previous deal with The Night Market, you should bring it to Ta'xera.\n\nYou will be fairly compensated.", completion = "A very dense list of names you have here. This will prove useful in my studies.", objectives = "Bring the Ledger of Souls to Ta'xera at The Night Market in Revendreth.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58075] = { id = 58075, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Favor: Dredger's Toolkit", description = "This item will be of great interest to the brokers. \n\nPer your previous deal with The Night Market, you should bring it to Ta'xera.\n\nYou will be fairly compensated.", completion = "Hmm, what's this? Ah, the proverbial tools of the trade.\n\nThis is of no interest to me, but my contacts interested in infrastructure would be most interested in this collection.", objectives = "Bring the Dredger's Toolkit to Ta'xera at The Night Market in Revendreth.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58077] = { id = 58077, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Favor: Perfected Hand Mirror", description = "This item will be of great interest to the brokers. \n\nPer your previous deal with The Night Market, you should bring it to Ta'xera.\n\nYou will be fairly compensated.", completion = "So finely crafted.\n\nThis must be the work of Laurent. Perfect for the transportation of persons around Revendreth in an inconspicuous manner. \n\nWe will make great use of this.", objectives = "Bring the Perfected Hand Mirror to Ta'xera at The Night Market in Revendreth.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58078] = { id = 58078, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Favor: Bottle of Redelav Wine", description = "This item will be of great interest to the brokers. \n\nPer your previous deal with The Night Market, you should bring it to Ta'xera.\n\nYou will be fairly compensated.", completion = "How decadent! Redelav wine! \n\nI'm torn on whether to keep it for my own collection or use this sought after wine for some valuable artifacts elsewhere.\n\nNevermind, here's your payment.", objectives = "Bring the Bottle of Redelav Wine to Ta'xera at The Night Market in Revendreth.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58079] = { id = 58079, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Favor: Pristine Dredbat Fang", description = "This item will be of great interest to the brokers. \n\nPer your previous deal with The Night Market, you should bring it to Ta'xera.\n\nYou will be fairly compensated.", completion = "What do you have here? Ah, an intact dredbat fang.\n\nPretty rare considering how... bitey they can be. Thank you for this.", objectives = "Bring the Pristine Dredbat Fang to Ta'xera at The Night Market in Revendreth.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58080] = { id = 58080, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Favor: Glittering Primrose Necklace", description = "This item will be of great interest to the brokers. \n\nPer your previous deal with The Night Market, you should bring it to Ta'xera.\n\nYou will be fairly compensated.", completion = "Oh how gorgeous. Very interesting.\n\n<Ta'xera inspects the necklace closely.>\n\nWhere did they get this material? I've not seen it in a long time. There is much to learn from it.", objectives = "Bring the Glittering Primrose Necklace to Ta'xera at The Night Market in Revendreth.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58081] = { id = 58081, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Favor: Love and Terror", description = "This item will be of great interest to the brokers. \n\nPer your previous deal with The Night Market, you should bring it to Ta'xera.\n\nYou will be fairly compensated.", completion = "Poems? From a venthyr?! \n\nSurprising to say the least. I can't wait to dig into the writing styles.", objectives = "Bring Love and Terror to Ta'xera at The Night Market in Revendreth.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58084] = { id = 58084, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Soul Snares" }
quests[58086] = { id = 58086, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Master of Lies", description = "Once more unto the fangs of death himself, sword drawn, peace with oblivion made. Let us meet death together and bring him low.\n\nBe sure you are prepared for a sustained assault. For once we reveal ourselves, there will be no stopping. \n\nWhen you are ready, direct the Focal Mirror at the gates of Castle Nathria. Let us descend upon our burning enemies with ferocity and swiftness of action.", completion = "What has he done?", objectives = "Defeat Sire Denathrius.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58087] = { id = 58087, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Destroying the Source", description = "Tidecaller Nezara is running the show. If we take her out, the remaining naga will break rank, but getting to her won't be easy. She's protected by a magical barrier that's drawing power from powercells nearby. \n\nIf we can destroy the source, we can destroy Nezara.", completion = "Tidecaller Nezara can't hide behind her barrier now!", objectives = "Destroy 3 Nazeshi Powercells within Dreadpearl Shallows.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58088] = { id = 58088, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Juicing Up", description = "I've conceived a task befitting of your \"talents\".\n\nHave you heard of the House of Plague? Crafters of toxins and potions. They suffered a tragic accident--a true, true shame.\n\nHerein lies the problem: I have long used the work of the plague devisers to bolster my arena performance. Without a potion of their creation, I'd find the fight unnecessarily taxing.\n\nThe brokers do have such potions, but they \"do not like my face.\" Could you obtain such a potion for me?", completion = "I know Scrapper Minoire sent you. She always enhances herself to win the fight.", objectives = "Find someone at the Challenger's Promenade who has enhancement potions.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58090] = { id = 58090, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Side Effects", description = "Scrapper Minoire's use of enhancers creates unpredictable betting implications. It is quite unhealthy... for our profits!\n\nFor a nominal fee, Au'larrynar can provide you with a \"special\" enhancer that Minoire will not be able to resist: a potion that turns the one who imbibes it into the ultimate combatant... and teaches them a lesson in restraint, as well.\n\nI cannot wait to see Minoire's next match in the arena!", progress = "This is an unexpected turn of events.", completion = "Scrapper Minoire will have to forfeit her spot in the contest.", objectives = "Deliver the potion to Scrapper Minoire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58092] = { id = 58092, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Halls of Atonement: Your Absolution", description = "The depravity outside of these halls is only a whisper of the true horrors being committed under the Lord Chamberlain's guidance inside the Halls of Atonement.\n\nIf you truly wish to curb this corruption, you must dethrone the imposter that you installed here.\n\nAtone for your own mistake. Kill the Lord Chamberlain, so that we may begin to restore permanent order to this place.", completion = "A large step in our journey to reclaim the honor of these halls... but not the last.\n\nI shall send word to the Accuser immediately.", objectives = "Kill the Lord Chamberlain inside the Halls of Atonement.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58093] = { id = 58093, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Our Forgotten Purpose", description = "I have no quarrel with you, Maw Walker.\n\nThe Lord Chamberlain and his abhorrent followers have debased these halls with their perversions of the rituals. Abusing souls and destroying their potential for pathetic mockeries of power.\n\nThe Accuser would never have allowed this. I have heard rumors that you may still be in contact with her. If so, please inform her of the situation here.\n\nShe will bring these depraved dogs to heel.", completion = "I am already working to undo the Lord Chamberlain's mistakes.\n\nYes, you may assist me.", objectives = "Meet the Accuser at Absolution Crypt.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
